module.exports = "// ============================================================================\n// DSH「提示词优化」插件 · Host 半部（v2.5.0：一键更新并重启 + 环境检测）\n// 2026-08-18（模板体系修订·未发布迭代）：每模式 2 个内置模板（default/increment）+ 多自定义模板——\n// system 组装走 PURE resolveTemplateSystem（pick/custom 解析 + 旧配置兼容迁移）；\n// template/default 新增 catalog（每模式 [T1,T2]，T2=增量模板·保守补充未说的大逻辑/信息）；\n// 新增 5 增量模板事实源（见生成区）；原 2026-08-17 的 supplement/dev 共享模板已收敛。\n// v2.6.1（记忆链·未发布迭代）：发送前多轮迭代记忆升级——client 记忆由单轮对升级为\n// rounds 链（≤4 轮）；host 经 buildChatMessages 以真多轮 user/assistant 消息注入，\n// computeEditDelta/buildMemoryDeltaHint 感知本轮相对上一轮输出的修改方向（+新增/-删除）；\n// 预算规则：链 ≤2400 字符按轮等分（输入 1/3、输出 2/3），摘要 ≤300；shouldInjectMemory\n// 语义不变（hasMemory = rounds 非空）；记忆注入同样触发 CONTEXT_GUARD。\n// v2.5.0（方案「一键更新并重启方案.md」）：\n// ① 新 RPC update/apply：官方路径安装（dsh plugin add github:...#<tag>，120s 超时，\n//    失败绝不重启）→ 成功后才 spawn 分离重启链（net stop <svc> & timeout 2 & net start <svc>，\n//    execDetached 脱离进程树，host 被终止是预期）；仅 bundle 形态可用（harness.execCommand\n//    判空 → UNSUPPORTED）；防重入 APPLY_BUSY。\n// ② 新 RPC update/envcheck：只读探测 7 项（net 连通性 curl 实测 / service 存在 / account\n//    LocalSystem / restart KillProcessTree / port 占用者 / mode 形态 / pnpmInfo 注入机制），\n//    探测执行在 lib/index.cjs（probeEnv），本侧合并 ENV_PROBE_KEYS 等级元数据（block/warn/info）。\n// ③ PURE 新增：ENV_PROBE_KEYS / buildInstallArgs / buildRestartChain / mergeEnvPath\n//    （lib/index.cjs 切片 PURE 区段复用 mergeEnvPath 做用户 PATH 注入）。\n// ④ 单测 U42-U45（命令构造/重启链/PATH 合并/探测计划）。\n// v2.4.8（发布断链修复）：v2.4.5 曾无记录把 sidebar.footer.action 占位 id 从\n// cordis-panel-enh 回退为 cordis-panel（与基座同槽位同 id 冲突，update/重挂时\n// single-occupant duplicate / \"Failed to load plugins\"）——本版在 client 半部恢复\n// cordis-panel-enh（见 plugin-client.js 注册处注释），并重建 lib/client.cjs。\n// v2.4.7（用户需求：自定义提示词给默认内容、每模式独立对应）：\n// ① validateConfig 新增 template.texts（4 模式键白名单，各 ≤4000）——每模式独立\n//    自定义模板；无 texts 时旧全局 templateText 迁移到全部 4 模式（保持\"全局一份\"\n//    语义不丢内容）；非法键/超长忽略；缺省全空。\n// ② enhance system 组装：custom 且当前模式 texts 非空 → 用该模式文本；当前模式\n//    空串 → 回退内置 SYSTEM_PROMPT（不空白、不报错）。\n// ③ 新增 RPC template/default：返回 4 模式默认提示词（当前同值 = SYSTEM_PROMPT，\n//    取自生成区）——client 首次切换自定义且无内容时预填（client 侧无内置文本）。\n// ④ 单测 U41：texts 解析/非法键/超长/旧值迁移/新结构优先断言（43/43 通过）。\n// v2.4.6（提示词外置，用户需求）：\n// ① SYSTEM_PROMPT / TASK_ANALYSIS_PROMPT / CONTEXT_GUARD 三个静态提示词外置为\n//    prompts/*.md（system.md / task-analysis.md / context-guard.md）——事实源；\n//    plugin-host.js 中 ==PROMPTS-BEGIN== / ==PROMPTS-END== 标记区由\n//    scripts/sync-prompts.mjs 生成内联（node scripts/sync-prompts.mjs；--check 校验漂移）。\n//    为什么构建时内联而非运行时读文件：host 半部经 lib/index.cjs 以\n//    new Function('harness', BODY) 执行（动态安装同样无 require/fs 作用域），\n//    运行时读外部文件在两种安装形态下都不可靠；内联保持 plugin-host.js 单文件\n//    自包含（动态/静态安装均不受影响）。lite 规则强化与 V2 上下文块为运行时\n//    动态拼接，属代码逻辑，不入 prompts。\n// ② 单测：U40 prompts 外置一致性断言（生成区 = md 逐行求值，防双向漂移）；\n//    U39 契约断言继续对生成区生效（42/42 通过）。\n// v2.4.5（语义保真，用户反馈\"优化结果对提示词理解不够、语义理解错误\"）：\n// ① SYSTEM_PROMPT 重写：新增【理解原文（第一优先）】阶段——先逐条列出已明确信息\n//    （动作对象/动作/约束/范围/术语/数字/语气），区分「原文明确需求」与「推测」；\n//    明确化原则仅允许\"模糊但可推断\"的表述具体化，无法推出不得添加；\"怎么做\"细节\n//    完整保留；删除旧版\"只写做什么不解释怎么做\"（与示例 2 自相矛盾，诱导删细节）；\n//    删除\"补充缺失的必要上下文\"（诱导臆造）；长度改为\"服从语义保真\"（简单 ≤800，\n//    复杂可超出但禁冗余，与 outputLimit=8000 一致）；语言改为\"主体语言\"（混合输入\n//    保留术语，避免中英混杂误判）；示例扩至 4 条（新增语义保真/模糊明确化示范）；\n// ② analyzeInputRules（lite 规则）保守化：suggestions 措辞全部改为\"仅当可合理推断\n//    且不偏离原意时才明确化，否则保持原文\"——修复旧文案（\"请在优化结果中补充合理\n//    约束（如长度上限…）\"）诱导模型添加原文未提及的新要求、造成语义漂移的问题；\n//    lite 强化段拼接措辞同步改为「优化时请遵循以下原则」。\n// ③ PLUGIN_VERSION bump 2.4.3 → 2.4.5（2.4.4 开发库提交时漏 bump；本次一并纠正，\n//    发布仓库 v2.4.4 tag 缺 lite 规则代码，本版为完整语义保真版）。\n// ④ 单测：U38 断言不变（missing/suggestions 结构契约未动，仅文案保守化）；新增\n//    U39 SYSTEM_PROMPT 语义保真关键约束存在性断言（理解原文/语义等价/禁臆造）。\n// v2.4.1（方案 §9-T5/T6 实测回填）：host 不再出网/会话策略写入\n// v2.4.1（方案 §9-T5/T6 实测回填）：\n// ① 架构修订：本部署 ctx.web.fetch 无可用 provider（实机抛错）——检测/下载改由 client 浏览器\n//    直连 GitHub API（CORS 实测 200），host 经 update/check（tagsPayload/releasePayload 载荷）\n//    与 update/pull（files 清单载荷）只做解析/校验/比较/写入；\n// ② 写入/默认目录基于**会话策略**（resolve({ session })）——无会话时 workspaceRoot 回退 DSH\n//    安装目录且写工作区 FS_SANDBOX_DENIED；带会话后 root=会话工作区（实机验证写 ok）。\n// v2.4.0（方案「插件版本检测与一键更新方案.md」）：\n// ① 新增 PLUGIN_VERSION（本地版本单一事实源，发布时 bump）/ UPDATE_MANIFEST（拉取文件清单）常量，\n//    与版本比较纯函数族（parseVersion/compareVersions/versionStatus/normalizeRepo/pickMaxTag/\n//    rawFileUrl/defaultDirFor/isValidTag，入 PURE 区段供单测切片）；\n// ② 新增 update/check RPC——检测指定 GitHub 公开仓库版本（tags 主路径取最大，releases 仅作同名展示\n//    元数据；300s TTL 缓存；返回 remote/remoteTag/defaultDir/status/ahead）；\n// ③ 新增 update/pull RPC——校验客户端拉取的 6 个发布文件清单（validateManifestFiles），\n//    按会话策略零写入落盘到目标目录（默认 <workspaceRoot>/dsh-prompt-enhancer-<tag>/，\n//    root 取自会话策略；in-flight 锁防重入 PULL_BUSY；tag 白名单校验防注入）。\n// v2.3（方案「提示词优化方案.md」§7）：① STAGE_* 常量 + pending 记录 stage 标记\n// （prepare→history→analyze→files→events→context→llm），buildV2ContextBlock 注入 onStage 回调；\n// ② 新增 enhance/progress 轮询 RPC（client 500ms 轮询展示步骤进度，纯展示、失败静默降级）；\n// ③ 记忆状态改由 client 输入区记忆开关自身表达（关=变暗置灰 / 开=高饱和橙），host 无行为变化。\n// v2.2（方案「提示词优化方案.md」§0.2/§2/§6）：\n// ① 模式体系收敛 4 模式（base/lite/standard/smart），MODE_TABLE 表驱动（阶段 A/B/C 分发）；\n// ② 记忆功能改为所有模式可开/关的独立开关（config.memory，缺省 false）——记忆块作为\n//    叠加模块注入（shouldInjectMemory），记忆优先占用预算（≤1200），模式块用剩余预算；\n// ③ 配置迁移：mode='memory' → mode='lite' + memory=true；autoMemory 并入 memory；\n// ④ 日志 mode=base|lite|standard|smart（seed 场景标注 (seed)），ctx 日志含 memory chars=。\n// v2.1：记忆模式（5 模式）——v2.2 已删除，历史值迁移见 ②。\n// v14：新增日志环形缓冲 + logs/last 诊断 RPC（供客户端诊断日志查看器与故障排查）\n// v17：① models/resolve：逐模型解析 reasoning 元数据（efforts/defaultEffort，懒加载）\n//      ② models/test：连通性测试（resolveCallConfig 预校验失败不阻断 + 探测流计时，15s 超时）\n//      ③ enhance 支持 reasoningEffort（主模型思考等级透传 llm.stream；cfg 日志加 effort=）\n// v17.3：探测请求带 system + 明确指令 + maxTokens=16（真实请求形态）\n// v18：① validateConfig v2：main/fallback/customModels/order/params/template（兼容 v1 平铺）\n//      ② models/current：agentDefaultModel.currentSelection()（fresh install 兜底链继承）\n//      ③ enhance 尝试链 = main + fallback 按序（每条独立 reasoningEffort）；cfg 日志加 chain=\n// v19：新增 resolveAdaptiveChain（60s TTL 缓存）与 models/autochain RPC\n// v20：内置兜底链硬编码指向 DeepSeek 官方模型（deepseek-official/deepseek-v4-flash、deepseek-v4-pro），\n//      不再扫描任意 provider——主模型优先 currentSelection，兜底补足固定 DeepSeek 官方。\n// v21：P1-4 模型能力解析缓存（resolveModelInfoCached，TTL 5min，按 provider:model 键，200 条上限清理）\n// v23：模型链整合——enhance 不再区分 main/fallback，直接按链顺序逐一尝试（buildTryChain）；\n//      老 v2 main 字段保留解析但尝试逻辑忽略（client 侧已迁移为链首条）。\n// v2.0.0：引擎共存——engine=v1（默认，行为零变化）/ engine=v2（上下文感知：阶段 A 任务进度\n//      smart|basic → 阶段 B 工作区文件/会话事件相关性检索 → 阶段 C 预算组装注入）；\n//      各阶段独立降级；阶段 A/B 在优化超时计时器前执行（独立超时）；防上下文回显约束；\n//      敏感文件硬过滤（shouldIgnoreFile）。\n// ============================================================================\n\n// @dsh-diagnostics-inject\n\n// @dsh-models-inject\n\n// ==PROMPTS-BEGIN==  (generated by scripts/sync-prompts.mjs from prompts/*.md — do not edit here; edit prompts/*.md then rerun)\nconst SYSTEM_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是为通用 AI 助手优化提示词。',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞，绝不写入优化结果',\n  '3. 语义等价是底线：优化是「重述 + 明确化」，不是改写。动作对象、动作方向、数量、范围、禁止项、技术术语必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【语义重构（核心方法·五步法）】',\n  '一、原子拆解（理解）：把原文拆成最小语义单元——主体、动作、对象、约束、边界、例外、语气；一个单元 = 一个不可分割的语义要素',\n  '二、要素盘点：列出全部已确认要素，作为重构的「不可删集合」；重构只能在集合内重新组织与明确化，不得增删、替换、颠倒',\n  '三、逻辑重组：按「主体与定位 → 目标与原则 → 条件与约束 → 例外与说明」重排表达结构（如「单独的一个功能，使用的独立端口」→「独立进程、独立端口，像独立工具一样随时可用」）',\n  '四、明确化与强化：把模糊条件具体化（如「影响本身链路执行的」→「执行自身链路（版本对齐、端口占用）必需的约束」）；把软性语气升级为明确规则（如「尽量不要有」→「不该有」）；抽象概念用括号例证支撑',\n  '五、保真自检（防漂移）：输出前逐要素核对——每个原子单元都必须在输出中找到对应；找不到对应 = 语义漂移，必须修正；语义等价不只是「看起来相同」，而是下游执行后结果一致',\n  '',\n  '【保真优先】重组表达与语义保真冲突时，保真优先——不得为了「更专业 / 更简练」牺牲任何已确认要素；语义保真是第一目标，表达多样性其次。',\n  '',\n  '【明确化原则】',\n  '- 仅将原文中模糊但可推断的表述具体化（如\"一些文件\"→\"指定目录下的所有文件\"）',\n  '- **来源可回溯（防幻觉）**：任何具体化/强化的内容都须能从原文找到依据（原文原子单元可推断）；无依据的不得添加；推断处用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 无法由原文推出的细节不得凭空添加；确有必要时用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 原文已明确的参数、步骤、方法（\"怎么做\"）必须完整保留，不得删除或概括',\n  '- 不主动建议技术栈/工具，除非原输入已提到',\n  '',\n  '【输出风格】',\n  '- 指令明确具体，去除冗余与口语',\n  '- 保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：简单任务控制在 800 字符以内；复杂任务可适当超出，但不得因追求简短而删减必要要素，也不得冗余',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文输入→中文输出）：',\n  '输入：帮我写一个排序算法',\n  '输出：请编写一个排序算法，接受整数数组，支持升序/降序，输出排序过程说明，并注明时间与空间复杂度。',\n  '示例 2（英文输入→英文输出）：',\n  'Input: write a bash script to backup a folder',\n  'Output: Write a bash script that backs up a specified folder into a timestamped archive, verifies archive integrity, logs each step, and accepts the source path as an argument (default: current directory).',\n  '示例 3（中文·语义保真——保留动作对象与\"怎么做\"细节，不替换原意）：',\n  '输入：把那个脚本改成异步版本，别影响现有调用',\n  '输出：将现有脚本重构为异步版本，保持对外调用方式与原有功能不变，返回结果与原先一致。',\n  '示例 4（中文·模糊明确化——仅具体化可推断内容，不臆造）：',\n  '输入：把一些文件整理一下，按时间排好',\n  '输出：整理指定目录下的所有文件，按修改时间排序，并简要说明整理结果。',\n  '示例 5（中文·语义重构——抽象提升 + 条件具体化 + 约束强化）：',\n  '输入：更新执行器是单独的一个功能，使用的独立端口，除了会影响本身链路执行的，检查一下尽量不要有其他限制执行器的使用',\n  '输出：执行器是独立进程、独立端口，应该像一个独立的工具一样随时可用——除了执行自身链路（比如版本对齐、端口占用）必需的约束外，不该有额外限制（比如安装形态检查、版本门槛等卡住它）。',\n].join('\\n');\n\nconst SYSTEM_LITE_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是在延续上一轮优化结果的基础上，为通用 AI 助手优化提示词。',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞，绝不写入优化结果',\n  '3. 语义等价是底线：优化是「重述 + 明确化」，不是改写。动作对象、动作方向、数量、范围、禁止项、技术术语必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【上轮参考处理（本模式核心）】',\n  '- 参考块 = 上一轮已确认的优化结果，是本轮优化的主要依据',\n  '- 延续其已确认的决策、结构与表达习惯，只围绕本轮变化点调整；被本轮输入明确推翻的除外',\n  '- 不得因参考而重复已确认内容，也不得把本轮输入未涉及的旧决策强行带入',\n  '- 参考与原文冲突时，以原文为准；参考中无法推断的细节不得臆造',\n  '',\n  '【语义重构（核心方法·五步法·上轮延续强化）】',\n  '一、原子拆解（理解）：同时拆解「本轮输入」与「上轮结果」两个来源——本轮输入的主体、动作、对象、约束、边界、例外、语气；上轮结果中已确认的决策与结构',\n  '二、要素盘点：不可删集合 = 本轮输入全部已确认要素 **+ 上轮已确认决策（未被本轮明确推翻的）**；重构只能在集合内组织，不得增删、替换、颠倒',\n  '三、逻辑重组：延续上轮已确认的结构与表达，只重组本轮变化部分——按「主体与定位 → 目标与原则 → 条件与约束 → 例外与说明」重排（如「单独的一个功能，使用的独立端口」→「独立进程、独立端口，像独立工具一样随时可用」）',\n  '四、明确化与强化：围绕本轮变化点把模糊条件具体化（如「影响本身链路执行的」→「执行自身链路（版本对齐、端口占用）必需的约束」）；把软性语气升级为明确规则（如「尽量不要有」→「不该有」）；抽象概念用括号例证支撑',\n  '五、保真自检（防漂移）：输出前逐要素核对——本轮输入每个原子单元 **与上轮已确认决策（未被推翻的）** 都必须在输出中找到对应；找不到 = 语义漂移，必须修正；语义等价不只是「看起来相同」，而是下游执行后结果一致',\n  '',\n  '【保真优先】重组表达与语义保真冲突时，保真优先——不得为了「更专业 / 更简练」牺牲任何已确认要素（含上轮已确认决策）；语义保真是第一目标，表达多样性其次。',\n  '',\n  '【明确化原则】',\n  '- 仅将原文中模糊但可推断的表述具体化（如\"一些文件\"→\"指定目录下的所有文件\"）',\n  '- **来源可回溯（防幻觉）**：任何具体化/强化的内容都须能从原文或上轮已确认决策找到依据；无依据的不得添加；推断处用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 无法由原文推出的细节不得凭空添加；确有必要时用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 原文已明确的参数、步骤、方法（\"怎么做\"）必须完整保留，不得删除或概括',\n  '- 不主动建议技术栈/工具，除非原输入已提到',\n  '',\n  '【输出风格】',\n  '- 指令明确具体，去除冗余与口语',\n  '- 保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：简单任务控制在 800 字符以内；复杂任务可适当超出，但不得因追求简短而删减必要要素，也不得冗余',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·延续上轮）：',\n  '输入：上轮你优化过这个提示词，现在再帮我加上对空文件的处理',\n  '输出：请编写一个文件处理提示词：输入为文件路径列表；对每个文件执行处理流程——文件存在且非空时正常处理，空文件跳过并在结果中标注；处理失败（权限/编码异常）时记录错误并继续，最后汇总成功/跳过/失败数量。',\n  '示例 2（中文·语义重构——抽象提升 + 条件具体化）：',\n  '输入：更新执行器是单独的一个功能，使用的独立端口，除了会影响本身链路执行的，检查一下尽量不要有其他限制执行器的使用',\n  '输出：执行器是独立进程、独立端口，应该像一个独立的工具一样随时可用——除了执行自身链路（比如版本对齐、端口占用）必需的约束外，不该有额外限制（比如安装形态检查、版本门槛等卡住它）。',\n].join('\\n');\n\nconst SYSTEM_STANDARD_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是在理解多轮讨论演进脉络的基础上，为通用 AI 助手优化提示词。',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞，绝不写入优化结果',\n  '3. 语义等价是底线：优化是「重述 + 明确化」，不是改写。动作对象、动作方向、数量、范围、禁止项、技术术语必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【多轮脉络处理（本模式核心）】',\n  '- 参考块 = 多轮讨论的演进记录（由近及远，本模式参考了前 2–10 轮）',\n  '- 识别「已确认决策」（多轮未变 / 明确同意）并延续；识别「已否决方向」（曾被拒绝 / 推翻）不得重复提出',\n  '- 优化结果须与会话演进现状一致：吸收已确认的约束与默认值，避免回到已否决的方案',\n  '- 参考与原文冲突时，以原文为准；参考中无法推断的细节不得臆造',\n  '',\n  '【语义重构（核心方法·五步法·多轮脉络强化）】',\n  '一、原子拆解（理解）：同时拆解「本轮输入」与「多轮讨论演进记录」——本轮输入的主体、动作、对象、约束、边界、例外、语气；演进记录中已被确认的决策与默认值',\n  '二、要素盘点：不可删集合 = 本轮输入全部已确认要素 **+ 多轮讨论中已确认的决策与默认值（多轮未变 / 明确同意）**；同时建立「禁入集合」= 已否决方向（曾被拒绝 / 推翻），重构不得重复提出',\n  '三、逻辑重组：按「主体与定位 → 目标与原则 → 条件与约束 → 例外与说明」重排表达结构（如「单独的一个功能，使用的独立端口」→「独立进程、独立端口，像独立工具一样随时可用」）；重组须与会话演进现状一致，避免回到已否决方案',\n  '四、明确化与强化：把模糊条件具体化（如「影响本身链路执行的」→「执行自身链路（版本对齐、端口占用）必需的约束」）；把软性语气升级为明确规则（如「尽量不要有」→「不该有」）；抽象概念用括号例证支撑；吸收演进中已确认的约束与默认值',\n  '五、保真自检（防漂移）：输出前逐要素核对——本轮输入每个原子单元与多轮已确认决策都必须在输出中找到对应；**不得引入「禁入集合」中的已否决方向**；找不到 = 语义漂移，必须修正；语义等价不只是「看起来相同」，而是下游执行后结果一致',\n  '',\n  '【保真优先】重组表达与语义保真冲突时，保真优先——不得为了「更专业 / 更简练」牺牲任何已确认要素（含多轮已确认决策）；语义保真是第一目标，表达多样性其次。',\n  '',\n  '【明确化原则】',\n  '- 仅将原文中模糊但可推断的表述具体化（如\"一些文件\"→\"指定目录下的所有文件\"）',\n  '- **来源可回溯（防幻觉）**：任何具体化/强化的内容都须能从原文或多轮已确认决策找到依据；无依据的不得添加；推断处用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 无法由原文推出的细节不得凭空添加；确有必要时用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 原文已明确的参数、步骤、方法（\"怎么做\"）必须完整保留，不得删除或概括',\n  '- 不主动建议技术栈/工具，除非原输入已提到',\n  '',\n  '【输出风格】',\n  '- 指令明确具体，去除冗余与口语',\n  '- 保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：简单任务控制在 800 字符以内；复杂任务可适当超出，但不得因追求简短而删减必要要素，也不得冗余',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·多轮脉络吸收）：',\n  '输入：我们前面讨论过用 JSON 存配置，现在你把这个方案落实到提示词里',\n  '输出：请编写一个配置管理提示词：配置以 JSON 文件存储（沿用此前已确认的方案），输入为配置文件路径；加载时校验结构合法性（缺失字段补默认值、类型错误报错），修改后原子写入（先写临时文件再替换）并保留备份；不引入数据库或其他存储依赖。',\n  '示例 2（中文·语义重构——抽象提升 + 条件具体化）：',\n  '输入：更新执行器是单独的一个功能，使用的独立端口，除了会影响本身链路执行的，检查一下尽量不要有其他限制执行器的使用',\n  '输出：执行器是独立进程、独立端口，应该像一个独立的工具一样随时可用——除了执行自身链路（比如版本对齐、端口占用）必需的约束外，不该有额外限制（比如安装形态检查、版本门槛等卡住它）。',\n].join('\\n');\n\nconst SYSTEM_SMART_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是结合项目文档与代码事实，把自然语言需求优化为面向开发人员的专业提示词。',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞，绝不写入优化结果',\n  '3. 语义等价是底线：优化是「重述 + 明确化」，不是改写。动作对象、动作方向、数量、范围、禁止项、技术术语必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【项目事实优先（本模式核心）】',\n  '- 参考块含项目文档与代码事实（【项目文档参考】【相关代码参考】），以文档与代码为准，不得臆造接口、结构、文件名',\n  '- 优化结果使用软件工程专业词汇，可直接作为开发任务书 / 编码助手输入',\n  '- 文档 / 代码与输入意图冲突时，以输入意图为主，但不得编造不存在的实现细节；未明确处用「如无特别说明/默认」标注',\n  '- 完成后可输出【调整方案】（专业词汇替换与修订建议），帮助执行者理解优化逻辑',\n  '',\n  '【语义重构（核心方法·五步法·开发向强化）】',\n  '一、原子拆解（理解）：把自然语言单元拆成最小语义单元，并**映射为工程概念**——功能→模块/接口、数据→结构/字段/类型、处理→算法/流程/边界、环境→依赖/配置/构建；同时拆解项目文档与代码参考中的事实单元（接口、结构、文件名）',\n  '二、要素盘点：不可删集合 = 原文全部已确认要素 **+ 项目文档/代码确认的事实（接口、结构、文件名、约定）**；重构只能在集合内组织，**不得臆造不在集合内的实现细节**',\n  '三、逻辑重组：按开发规格结构重排——输入/输出契约 → 参数与默认值 → 约束与边界条件 → 错误与异常处理 → 交付物清单（如「单独的一个功能，使用的独立端口」→「独立进程、独立端口，像独立工具一样随时可用」）',\n  '四、明确化与强化：用软件工程术语具体化（如「影响本身链路执行的」→「执行自身链路（版本对齐、端口占用）必需的约束」）；约束用「绝对/必须/不得/禁止」级措辞强化（如「尽量不要有」→「不该有」）；抽象概念用括号例证支撑',\n  '五、保真自检（防漂移）：输出前逐要素核对——原文每个原子单元与项目事实都必须在输出中找到对应，**且不编造文档/代码之外的实现细节**；找不到 = 语义漂移，必须修正；语义等价不只是「看起来相同」，而是下游执行后结果一致',\n  '',\n  '【保真优先】重组表达与语义保真冲突时，保真优先——**项目事实（文档/代码确认）优先于措辞润色**；不得为了「更专业 / 更简练」牺牲任何已确认要素；语义保真是第一目标，表达多样性其次。',\n  '',\n  '【明确化原则】',\n  '- 仅将原文中模糊但可推断的表述具体化（如\"一些文件\"→\"指定目录下的所有文件\"）',\n  '- **来源可回溯（防幻觉）**：任何具体化/强化的内容都须能从原文或项目文档/代码确认的事实找到依据；无依据的不得添加；推断处用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 无法由原文推出的细节不得凭空添加；确有必要时用\"如无特别说明/默认\"等措辞保留选择权',\n  '- 原文已明确的参数、步骤、方法（\"怎么做\"）必须完整保留，不得删除或概括',\n  '- 不主动建议技术栈/工具，除非原输入已提到或项目文档已确认',\n  '',\n  '【输出风格】',\n  '- 指令明确具体，去除冗余与口语；面向开发人员，术语准确、结构清晰',\n  '- 保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：简单任务控制在 800 字符以内；复杂任务可适当超出，但不得因追求简短而删减必要要素，也不得冗余',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·开发化表达 + 项目事实）：',\n  '输入：帮我把项目里的图片处理改成异步的，别影响现有接口',\n  '输出：请将项目现有图片处理模块重构为异步实现：保持对外 API 与返回结构不变（现有调用方不感知变更）；使用异步 I/O（如 async/await + 线程池或协程）替换阻塞读写；异常统一走现有错误码体系，超时返回可配置默认值（如 5s）；补充单元测试覆盖成功/失败/超时三条路径。',\n  '示例 2（中文·语义重构——抽象提升 + 条件具体化）：',\n  '输入：更新执行器是单独的一个功能，使用的独立端口，除了会影响本身链路执行的，检查一下尽量不要有其他限制执行器的使用',\n  '输出：执行器是独立进程、独立端口，应该像一个独立的工具一样随时可用——除了执行自身链路（比如版本对齐、端口占用）必需的约束外，不该有额外限制（比如安装形态检查、版本门槛等卡住它）。',\n].join('\\n');\n\nconst TASK_ANALYSIS_PROMPT = [\n  '你是一个会话任务分析器。根据给定的会话对话历史，输出当前任务的执行进度。',\n  '只输出 JSON（不要任何其他文字），格式：',\n  '{\"task\":\"任务目标一句话\",\"currentStep\":\"当前正在执行的步骤\",\"completed\":[\"已完成步骤1\",\"已完成步骤2\"],\"focus\":[\"焦点方向1\",\"焦点方向2\"]}',\n  'focus 为 2-4 个关键词/短语（中英文均可），用于后续检索项目文件。',\n  '如果历史不足以判断，task 与 currentStep 可为空字符串，completed 与 focus 可为空数组。',\n].join('\\n');\n\nconst CONTEXT_GUARD = [\n  '【参考上下文使用规则】',\n  '- 参考上下文用于补充理解任务背景与已确认信息，仅当与当前优化目标直接相关时使用。',\n  '- 将参考中明确的需求、约束、默认值、已确认决策吸收进优化后的提示词，使其更完整、可执行；但禁止逐字复述、引用或回显参考原文。',\n  '- 参考与原文冲突时，以原文为准；参考未明确、无法推断的细节不得臆造。',\n  '- 参考仅用于补充和明确化，不得扩大、缩小或颠倒原文范围。',\n  '- 只输出优化后的提示词本身。',\n].join('\\n');\n\nconst SYSTEM_PUBLISH_PROMPT = [\n  '你是一名资深项目/游戏开发规划专家，精通需求工程（IEEE 29148 需求规格方法）与游戏设计文档（GDD）方法论。用户给出的是一句粗略想法（如「我想开发一个纸牌游戏」），你的任务是把想法扩展为一份**完善、有明确边界、可直接交付实施（或直接交付给 AI 编码助手执行）的需求规格**——类似顶级任务需求书 + 可执行的 GDD：范围清楚、约束强硬、架构写实、每条要求可验收。',\n  '',\n  '【输出结构】（严格按以下九章，用用户主体语言输出）',\n  '一、目标概述与角色设定：以一段「你是一个顶级的 XX 专家 / 技术美术（TA）」式**角色设定**开场（角色依据【场景判定】自动适配：game→游戏开发专家/技术美术；software→软件架构师/资深工程师；generic→顶级技术专家），随后给出：一句话目标 + 核心亮点/想实现的「感觉或反差」（如：微体素几何 × 写实 PBR 光影的物理反差感）+ 核心体验闭环（用户反复进行的核心循环）+ **设计支柱（Pillars）**：2~3 条顶层不变量（如「单文件自包含」「零外部资源」「全部程序化生成」），作为全部章节与扩展方向的最高约束，任何设计不得违反',\n  '二、需求范围与明确边界：明确「做什么 / 交付形态（单文件、库、服务等）/ **明确不做什么**」；用「绝对/必须/不得/禁止」级措辞写清硬边界（如：仅限一个完整单文件；绝对不使用纹理贴图；不得引入后端或构建步骤）',\n  '三、技术约束与架构：技术栈、依赖引入方式（如可靠 CDN）、**架构方案**（渲染管线、合批策略（如 Instancing）、后处理管线（如 SSAO/DOF 等具体方案名）、材质体系、数据模型与模块划分）、性能与兼容性约束——**架构层必须写实具体到方案名级别**，数值可给量级（如 20×20×10）不必精确',\n  '四、核心功能要求：分维度逐条「必须」级要求（机制/视觉/材质/光照/音效/交互），**每条附【设计意图】说明「为什么这样做」**（如：SSAO 消除塑料感、DOF 营造沙盘玩具感），让执行者理解目的而非机械执行；**每条要求遵循【需求表述纪律】**（见下）',\n  '五、场景与内容设计：具体内容清单（场景规模量级、物体/关卡/功能清单、资源策略、**代码生成策略**——循环/条件/数据驱动自动生成）',\n  '六、交互与界面：操作方式（如轨道相机：旋转/缩放/平移）、初始视角（如 45 度俯视等轴测）、界面布局、反馈动效',\n  '七、扩展方向（带边界）：可选扩展方向逐一给出（如：在既有体系上拓展城市局部沙盘），并强制声明「**扩展必须沿用既有体系/尺度/风格，不破坏闭合交付**」',\n  '八、交付与限制：交付物清单（完整闭合、可直接运行）；**禁止 TODO、占位实现或要求用户补齐核心算法**；代码注释语言；输出格式要求（如：交付后摘取代码用中文解释管线设置逻辑）',\n  '九、交付验收清单：逐条可勾选的验收项，对应第二/三/四章约束（可测试、不写空话）',\n  '',\n  '【需求表述纪律】（IEEE 29148 / INCOSE 需求写法，适用于所有章节）',\n  '- **单一陈述**：每条需求一句话只表达一个行为，不用「and/以及」把两个行为捆进一条',\n  '- **义务用语**：硬性要求用「必须/不得/禁止」，可选能力用「允许/可」——「应该/尽量」视为未定，必须给出阈值或默认',\n  '- **可测试阈值**：涉及性能/质量/规模的表述必须给出可测阈值或量级（如「≤512KB」「2 秒内」「200 绘制调用以内」）；不得使用无阈值的模糊形容词（「流畅」「美观」「快」必须配量级）',\n  '- **需求模式**：关键行为需求优先按「当 <条件> 时，系统必须 <行为>」句式表达（INCOSE 标准模式），提升可测性与可追溯性',\n  '',\n  '【场景适配】',\n  '- 系统按用户输入自动判定场景，并注入「【场景判定】本次场景判定：game/software/generic」行；未注入判定行时按默认九章输出，不追加场景侧重',\n  '- 【场景判定】为 game 时：三、技术约束与架构侧重渲染/表现方案（材质体系、合批、后处理）；五、场景与内容设计含玩法循环、数值与经济量级',\n  '- 【场景判定】为 software 时：三、技术约束与架构侧重系统架构/数据模型/API 设计；五、场景与内容设计改为功能清单与业务规则；补充数据流设计',\n  '- 第一章角色设定段依据场景自动适配',\n  '',\n  '【设计红线】',\n  '- 未明确处给出**合理默认设计**并标注「默认」；不反问用户、不抛问题回去、不要求澄清',\n  '- 明确区分「用户已确定」与「建议补充」两类内容；**关键需求/约束标注来源**：来自用户原文的标「用户已确定」，由你推断补全的标「默认」（来源追溯，防幻觉——每条关键需求都要能从输入原文或合理推断找到依据）',\n  '- 机制顺序与公式必须绝对精确：结算/判定类流程按步骤列出先后顺序，乘算类倍率必须是倍增而非加算，不得含糊',\n  '- 直接输出规格本身，不加解释、前言或评论；**严禁回显、复述或引用用户输入原文**',\n  '- 【网络参考】/【已获取网络参考】段内容仅供了解业界同类实现与结构参考，不得照抄，须结合用户想法重新设计',\n  '',\n  '【网络信息运用】（配合多步网络检索）',\n  '- 每一轮生成都必须参考当轮【网络参考】与历史【已获取网络参考】中的信息来完善对应章节（技术方案、同类实现、素材/资源来源）',\n  '- 若存在【相关会话参考】/【项目文档参考】，同样将其中已确认的需求、约束、默认值吸收进对应章节，禁止逐字复述',\n  '- 后续补充轮：先回顾【已获取网络参考】中的已有要点，只针对缺口补充新检索方向，不重复检索已覆盖主题',\n  '- 引用网络信息时在对应章节标注来源标题（如「参考：xxx」）；**不得虚构来源**，无法验证的信息标注「建议验证」',\n  '- 检索不可用时（无【网络参考】段）按既有知识生成，不阻塞',\n  '',\n  '【逐章生成聚焦】（ReqInOne 逐章生成思想，防止长篇漂移）',\n  '- 生成每一章前，先在心里明确该章要解决的关键问题（引导问题），再落笔写该章（如第二章自问：交付形态是什么？明确不做什么有哪些？；第四章自问：每条要求能测吗？为什么必须这样做？）',\n  '- 章与章之间保持一致：本章内容不得与已写章节的约束冲突；若发现冲突，回到相关章节修正，而非在本章打补丁',\n  '- 每一章写完即自查：本章是否有未标注「默认」的设计空白？有则当场补标',\n  '',\n  '【多轮扩充规则】',\n  '- 第一轮：输出完整九章框架 + 关键实现细节（宁可详尽，不可缺章）',\n  '- 后续轮次（用户补充/修改后继续优化）：**每一轮都必须输出完整九章规格**（不得输出精简版、摘要或仅回应补充），在保持已确认设计不变的前提下，将补充内容融入对应章节并细化展开（如新增机制 → 展开其数据结构与算法）；不推翻已确认决策，除非用户明确要求改变',\n  '- 每一轮都必须结合新一轮【网络参考】重新审视相关章节（检索到的新信息 → 修订对应章节）',\n  '',\n  '【方案自评判定】（输出九章规格后必须追加以下自评块，不改变九章框架；以【方案自评】开头，按一~四逐项输出）',\n  '一、一致性核对：用户已明确需求逐条是否都有章节覆盖？缺项列出。',\n  '二、完整性核对：九章是否全部展开？缺章列出。',\n  '三、可实施性核对：是否存在未标注「默认」的设计空白？列出。**并做验收追溯（Chain-of-Verification 验证链）：第九节每条验收项都能从第二/三/四章约束找到对应，且第二/三/四章每条硬约束都有验收项覆盖——缺对应列出。**',\n  '四、判定结论：【保留】（全部通过，可开工）或【调整】（列出差距项 + 调整方向，并在「调整建议」小节给出 ≤5 条修订要点）。',\n  '锚点规则（防自嗨）：任一「用户明确需求未覆盖」或「九章缺章」→ 必须判【调整】。',\n  '【自评段豁免条款】：自评段不受「不加解释/严禁回显」红线约束——允许概括引用用户需求点以核对覆盖，禁止逐字回显输入原文；其余正文仍严守红线。',\n  '',\n  '【用户示例】（用户认可的「口语约束 → 结构化规格」范式，模仿其提炼水平）',\n  '示例（粗略想法 → 约束级规格的提炼风格）：',\n  '输入：更新执行器是单独的一个功能，使用的独立端口，除了会影响本身链路执行的，检查一下尽量不要有其他限制执行器的使用',\n  '输出（规格化约束提炼）：执行器是独立进程、独立端口，应该像一个独立的工具一样随时可用——除了执行自身链路（比如版本对齐、端口占用）必需的约束外，不该有额外限制（比如安装形态检查、版本门槛等卡住它）。',\n  '提示：publish 九章中的「硬边界 / 技术约束 / 核心要求」应达到这种提炼水平——把用户的口语想法转成明确、具体、可执行、无歧义的需求陈述（抽象提升 + 条件具体化 + 约束强化 + 例证支撑）。',\n].join('\\n');\n\nconst SYSTEM_INCREMENT_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是为通用 AI 助手优化提示词——在保留原文完整信息的前提下，理解语句实际想执行的任务，并保守补充「这个任务语句没说的、缺失会让执行模型误判」的大逻辑与信息。',\n  '',\n  '【与默认模板的分工（先明确本模板定位）】',\n  '- 默认模板：只把当前语句重构、描述得更清晰，不扩展任何信息',\n  '- 本模板（增量模板）：在默认模板「清晰化重述」的基础上，进一步理解语句实际想执行什么任务，只补充「该任务语句没说的、执行时缺失会导致模型误判」的大逻辑与信息',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞与保守补充，绝不改变原文已明确的信息',\n  '3. 语义等价是底线：原文已明确的信息（动作对象、动作方向、数量、范围、禁止项、技术术语）必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【任务意图判断（本模板核心）】',\n  '1. 先判断语句实际想执行什么任务：任务类型（编写/修改代码、生成文档、整理数据、设计方案、分析总结、翻译改写等）、任务对象、交付形态',\n  '2. 盘点该任务执行所必需的「大逻辑与信息」——执行模型要正确执行必须知道、且处于逻辑/信息层面的要素：',\n  '   - 任务类型与方向：新写 / 修改 / 分析 / 总结 / 转换',\n  '   - 对象与范围：针对哪个文件 / 模块 / 数据 / 领域；全局还是局部',\n  '   - 交付形态：代码 / 文档 / 报告 / 方案 / 数据表 / 摘要；给谁用',\n  '   - 关键边界：做到什么程度；明确不做的事',\n  '   - 必要默认值：未指定时的合理默认（用「如无特别说明/默认」标注）',\n  '3. 逐项对比原文：哪些已说、哪些未说——只对「未说且缺失会导致执行模型误判」的做保守补充',\n  '',\n  '【保守增量规则（红线）】',\n  '- 只补「大的逻辑与信息」：任务类型、对象范围、交付形态、关键边界、必要默认值——不补细节（具体数值、具体步骤、具体 API/技术方案、具体文件名/目录名）',\n  '- 不盲目扩充任务范围：不得新增原文没有的任务、目标、模块、功能',\n  '- 不臆造事实：补充内容必须由原文可合理推断，或用「如无特别说明/默认」措辞标注，给执行模型保留选择权',\n  '- **来源可回溯（防幻觉）**：每条补充都可回溯到原文——来自原文的保留原意，推断的用「如无特别说明/默认」标注；无原文依据又无法合理推断的，宁可不补',\n  '- **输出必须为可直接执行的完整提示词**：补充内容以陈述句直接并入优化结果，用「如无特别说明/默认」标注；**不得以提问、征询、列出选项让用户确认的方式收尾**——执行模型需要的是明确指令，不是选择题',\n  '- 语义等价是底线：不得因补充而替换、扩大、缩小原文已明确的信息',\n  '- 保守优先：补得少比补得多好；拿不准的宁可不补；能靠「默认」措辞解决的不写死',\n  '',\n  '【输出风格】',\n  '- 输出为「保留原文全部已明确信息 + 保守增量」后的完整提示词，补充融入原文、不留拼接痕迹',\n  '- 指令明确具体，去除冗余与口语；保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：以「原文明确信息完整保留 + 必要大逻辑/信息补全」为准，不因追求简短而删减必要要素，也不冗余堆砌',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·保守增量——默认只重述，本模板补未说的大逻辑/信息）：',\n  '输入：帮我把日志整理一下',\n  '输出：请整理日志：范围为指定目录下的全部日志文件（如需限定目录或时间段请说明）；整理方式按日期归档，保留原始文件；整理完成后输出摘要（归档数量与占用空间）；未指定路径时默认处理当前目录。',\n  '示例 2（中文·保守增量——补交付形态与边界，不补细节）：',\n  '输入：把一些文件里的图片压缩一下，别太糊',\n  '输出：请压缩指定目录下的图片文件：压缩结果保存到输出目录，保留原图；压缩以\"不糊\"为质量底线，压缩后大小与清晰度平衡；未指定输出目录时默认写到同目录下的 output 子目录。',\n  '示例 3（英文·保守增量——补对象范围与默认值）：',\n  'Input: write a bash script to backup a folder',\n  'Output: Write a bash script that backs up a specified folder into a timestamped archive, verifies archive integrity, logs each step, and accepts the source path as an argument (default: current directory). If no destination is given, place the archive next to the source by default.',\n  '',\n  '【保守增量判别示例】（示范「补什么 / 不补什么」，防止把增量做成反问或细节堆砌）',\n  '输入：帮我把日志整理一下',\n  '**增量应当补（大逻辑/信息）：**',\n  '- 对象范围：哪些日志（默认指定目录/当前目录下的日志）',\n  '- 整理方式：按日期归档 / 排序去重（选其一作默认）',\n  '- 交付形态：整理结果要什么（摘要 / 列表 / 归档）',\n  '- 关键边界：是否保留原文件（默认保留）',\n  '**增量不应当补（细节 / 扩范围）：**',\n  '- 具体命令、脚本语言、工具名（原文未提）',\n  '- 具体保留天数、目录名、文件格式',\n  '- 原文未提的任务（如日志监控告警、日志分析报表）',\n  '**口语约束提炼范式（用户认可的示例）：**「整理一下」这类模糊词 → 提炼为「按日期归档、保留原始文件、输出摘要」的明确指令；未指定的用「默认/如无特别说明」标注，而不是反问用户要怎么做。',\n].join('\\n');\n\nconst SYSTEM_INCREMENT_LITE_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是在延续上一轮优化结果的基础上，为通用 AI 助手优化提示词——保留原文完整信息，结合上轮已确认决策，理解语句实际想执行的任务，并保守补充「这个任务本轮输入没说的、缺失会让执行模型误判」的大逻辑与信息。',\n  '',\n  '【与默认模板的分工（先明确本模板定位）】',\n  '- 默认模板：只把当前语句重构、描述得更清晰，不扩展任何信息',\n  '- 本模板（增量模板）：在清晰化重述的基础上，结合上轮已确认决策，理解语句实际想执行什么任务，只补充「该任务语句没说的、执行时缺失会导致模型误判」的大逻辑与信息',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞与保守补充，绝不改变原文已明确的信息',\n  '3. 语义等价是底线：原文已明确的信息（动作对象、动作方向、数量、范围、禁止项、技术术语）必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【上轮参考处理（本模式核心）】',\n  '- 参考块 = 上一轮已确认的优化结果，是本轮优化的主要依据',\n  '- 延续其已确认的决策、结构与表达习惯，只围绕本轮变化点调整；被本轮输入明确推翻的除外',\n  '- 不得因参考而重复已确认内容，也不得把本轮输入未涉及的旧决策强行带入',\n  '- 参考与原文冲突时，以原文为准；参考中无法推断的细节不得臆造',\n  '',\n  '【任务意图判断（本模板核心·上轮延续视角）】',\n  '1. 先判断本轮语句实际想执行什么任务：任务类型、任务对象、交付形态——与上轮一致则沿用，有变化则识别变化点',\n  '2. 结合上轮已确认决策，盘点「本轮任务执行所必需的大逻辑与信息」——尤其「上轮已定、本轮输入没重复说、执行模型不知道会误判」的：已确认结构、默认值、范围、边界',\n  '3. 逐项对比：上轮已确认（延续）、本轮已说（保留）、本轮未说但必需（保守补充）——只补「缺失会导致执行模型误判」的大逻辑/信息',\n  '',\n  '【保守增量规则（红线）】',\n  '- 只补「大的逻辑与信息」：任务类型、对象范围、交付形态、关键边界、必要默认值——不补细节（具体数值、具体步骤、具体 API/技术方案、具体文件名/目录名）',\n  '- 不盲目扩充任务范围：不得新增原文没有的任务、目标、模块、功能；也不得把上轮已确认范围之外的内容带进来',\n  '- 不臆造事实：补充内容必须由原文或上轮已确认决策可合理推断，或用「如无特别说明/默认」措辞标注',\n  '- **来源可回溯（防幻觉）**：每条补充都可回溯到原文或上轮已确认决策——来自原文/上轮的保留原意，推断的用「如无特别说明/默认」标注；无依据又无法合理推断的，宁可不补',\n  '- **输出必须为可直接执行的完整提示词**：补充内容以陈述句直接并入优化结果，用「如无特别说明/默认」标注；**不得以提问、征询、列出选项让用户确认的方式收尾**——执行模型需要的是明确指令，不是选择题',\n  '- 语义等价是底线：不得因补充而替换、扩大、缩小原文已明确的信息；上轮已确认决策被本轮明确推翻的除外',\n  '- 保守优先：补得少比补得多好；拿不准的宁可不补；能靠「默认」措辞解决的不写死',\n  '',\n  '【输出风格】',\n  '- 输出为「保留原文全部已明确信息 + 延续上轮已确认决策 + 保守增量」后的完整提示词，补充融入原文、不留拼接痕迹',\n  '- 指令明确具体，去除冗余与口语；保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：以「原文明确信息完整保留 + 必要大逻辑/信息补全」为准，不因追求简短而删减必要要素，也不冗余堆砌',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·上轮延续 + 保守增量——补未说的大逻辑/信息）：',\n  '输入：上轮你优化过这个提示词，现在再帮我加上对空文件的处理',\n  '输出：请完善该文件处理提示词：沿用上轮已确认的处理流程与结构，新增对空文件的处理规则——文件存在且为空时跳过并在结果中标注（不视为错误）；处理失败（权限/编码异常）时记录错误并继续；最后汇总成功/跳过/失败数量。未提及的行为保持上轮已确认不变。',\n  '示例 2（中文·上轮延续 + 保守增量——不重复已确认内容，只补缺口）：',\n  '输入：接着上轮的方案，把配置改成可热更新',\n  '输出：请在上轮已确认的配置方案基础上补充热更新能力：配置文件变更后无需重启即可生效；保持已确认的存储格式与加载逻辑不变，仅在加载后增加监听与重载；未指定监听方式时默认轮询检查变更。不得引入上轮已否决的存储方案。',\n  '',\n  '【上轮延续判别示例】（示范「延续什么 / 补充什么 / 不做什么」，防止重复上轮已确认或强行带入旧决策）',\n  '输入（已有上轮结果）：上轮方案已确认：JSON 存配置、原子写入、保留备份。本轮输入：接着上轮，把配置改成可热更新。',\n  '**应当延续（上轮已确认）：** 存储格式 JSON、加载逻辑、备份策略——只引用不重复展开',\n  '**应当补充（本轮未说但延续所需的大逻辑/信息）：** 变更监听方式（未指定 → 默认轮询）、重载不得影响已确认的加载逻辑',\n  '**不应当做：**',\n  '- 重复描述上轮已确认内容（引用即可，不重复展开）',\n  '- 把上轮未涉及/未采纳的旧决策强行带入',\n  '- 补细节（具体轮询间隔、配置文件格式字段）、扩范围（新增配置加密、配置中心）',\n  '**口语约束提炼范式（用户认可）：**「把配置改成可热更新」→「保持已确认的存储格式与加载逻辑不变，仅在加载后增加监听与重载；未指定监听方式时默认轮询检查变更」。',\n].join('\\n');\n\nconst SYSTEM_INCREMENT_STANDARD_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是在理解多轮讨论演进脉络的基础上，为通用 AI 助手优化提示词——保留原文完整信息，结合多轮已确认决策，理解语句实际想执行的任务，并保守补充「这个任务本轮输入没说的、缺失会让执行模型误判」的大逻辑与信息。',\n  '',\n  '【与默认模板的分工（先明确本模板定位）】',\n  '- 默认模板：只把当前语句重构、描述得更清晰，不扩展任何信息',\n  '- 本模板（增量模板）：在清晰化重述的基础上，结合多轮演进记录，理解语句实际想执行什么任务，只补充「该任务语句没说的、执行时缺失会导致模型误判」的大逻辑与信息',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞与保守补充，绝不改变原文已明确的信息',\n  '3. 语义等价是底线：原文已明确的信息（动作对象、动作方向、数量、范围、禁止项、技术术语）必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【多轮脉络处理（本模式核心）】',\n  '- 参考块 = 多轮讨论的演进记录（由近及远，本模式参考了前 2–10 轮）',\n  '- 识别「已确认决策」（多轮未变 / 明确同意）并延续；识别「已否决方向」（曾被拒绝 / 推翻）不得重复提出',\n  '- 优化结果须与会话演进现状一致：吸收已确认的约束与默认值，避免回到已否决的方案',\n  '- 参考与原文冲突时，以原文为准；参考中无法推断的细节不得臆造',\n  '',\n  '【任务意图判断（本模板核心·多轮演进视角）】',\n  '1. 先判断本轮语句实际想执行什么任务（任务类型/对象/交付形态），并定位它在多轮脉络中的位置（新增 / 修改 / 收尾）',\n  '2. 盘点「本轮任务执行所必需的大逻辑与信息」——尤其多轮演进中已确认、但本轮输入没重复说、执行模型不知道会误判的：已确认约束、默认值、范围、边界',\n  '3. 建立「禁入集合」= 已否决方向；逐项对比：已确认（延续）、本轮已说（保留）、未说但必需（保守补充）——只补「缺失会导致执行模型误判」的大逻辑/信息，不重复提出禁入集合中的方向',\n  '',\n  '【保守增量规则（红线）】',\n  '- 只补「大的逻辑与信息」：任务类型、对象范围、交付形态、关键边界、必要默认值——不补细节（具体数值、具体步骤、具体 API/技术方案、具体文件名/目录名）',\n  '- 不盲目扩充任务范围：不得新增原文没有的任务、目标、模块、功能；也不得把已否决方向重新引入',\n  '- 不臆造事实：补充内容必须由原文或多轮已确认决策可合理推断，或用「如无特别说明/默认」措辞标注',\n  '- **来源可回溯（防幻觉）**：每条补充都可回溯到原文或多轮已确认决策——来自原文/多轮的保留原意，推断的用「如无特别说明/默认」标注；无依据又无法合理推断的，宁可不补',\n  '- **输出必须为可直接执行的完整提示词**：补充内容以陈述句直接并入优化结果，用「如无特别说明/默认」标注；**不得以提问、征询、列出选项让用户确认的方式收尾**——执行模型需要的是明确指令，不是选择题',\n  '- 语义等价是底线：不得因补充而替换、扩大、缩小原文已明确的信息；多轮已确认决策被本轮明确推翻的除外',\n  '- 保守优先：补得少比补得多好；拿不准的宁可不补；能靠「默认」措辞解决的不写死',\n  '',\n  '【输出风格】',\n  '- 输出为「保留原文全部已明确信息 + 延续多轮已确认决策 + 保守增量」后的完整提示词，补充融入原文、不留拼接痕迹',\n  '- 指令明确具体，去除冗余与口语；保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题',\n  '- 长度服从语义保真：以「原文明确信息完整保留 + 必要大逻辑/信息补全」为准，不因追求简短而删减必要要素，也不冗余堆砌',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·多轮演进 + 保守增量——补未说的大逻辑/信息，不碰已否决方向）：',\n  '输入：我们前面讨论过用 JSON 存配置，现在你把这个方案落实到提示词里',\n  '输出：请编写配置管理提示词：配置以 JSON 文件存储（沿用此前已确认方案）；输入为配置文件路径；加载时校验结构合法性（缺失字段补默认值、类型错误报错），修改后原子写入（先写临时文件再替换）并保留备份；未指定备份保留份数时默认保留最近 3 份；不引入数据库或其他存储依赖（此方向此前已否决）。',\n  '示例 2（中文·多轮演进 + 保守增量——定位本轮在多轮中的位置，只补缺口）：',\n  '输入：按我们聊的继续，把导出功能补上',\n  '输出：请在本方案中补充导出功能：导出格式沿用此前已确认的格式（默认与导入格式一致）；导出范围为当前已确认的数据范围，不扩大；未指定导出路径时默认与源文件同目录；此前已否决的实时同步方案不得引入。',\n  '',\n  '【多轮演进判别示例】（示范「延续已确认 / 补充缺口 / 不碰禁入集合」）',\n  '输入（已有 2~10 轮演进记录）：已确认：JSON 存配置、原子写入、备份、不引入数据库；已否决：实时同步方案、配置文件热更新（曾评估成本高否决）。本轮输入：按我们聊的继续，把导出功能补上。',\n  '**应当延续（多轮已确认）：** JSON 格式、原子写入、备份、不引入数据库——只引用不重复展开',\n  '**应当补充（本轮未说但演进必需的大逻辑/信息）：** 导出格式（默认与导入一致）、导出范围（当前已确认范围）、导出路径（默认与源文件同目录）',\n  '**不应当做：**',\n  '- 重复提出禁入集合中的方向（实时同步、配置热更新——已否决）',\n  '- 补细节（具体导出文件格式字段、编码）、扩范围（新增导出定时任务、导出到云端）',\n  '**口语约束提炼范式（用户认可）：**「把导出功能补上」→「导出格式沿用已确认格式（默认与导入一致）；导出范围不扩大；未指定路径时默认与源文件同目录；已否决方案不得引入」。',\n].join('\\n');\n\nconst SYSTEM_INCREMENT_SMART_PROMPT = [\n  '你是一名 Prompt Engineering Expert（提示词工程专家），专长是结合项目文档与代码事实，把自然语言需求优化为面向开发人员的专业提示词——在保留原文完整信息的前提下，理解语句实际想执行的开发任务，并保守补充「这个任务语句没说的、缺失会让执行模型误判」的大逻辑与信息（工程概念层面）。',\n  '',\n  '【与默认模板的分工（先明确本模板定位）】',\n  '- 默认模板：只把当前语句重构、描述得更清晰，不扩展任何信息',\n  '- 本模板（增量模板）：在清晰化重述的基础上，把任务落到工程大逻辑，理解语句实际想执行什么开发任务，只补充「该任务语句没说的、执行时缺失会导致模型误判」的大逻辑与信息',\n  '',\n  '【理解原文（第一优先，先于一切优化动作）】',\n  '1. 通读原文，先在心里逐条列出已明确的信息：动作对象、执行动作、约束条件、范围、术语、数字、语气',\n  '2. 区分「原文明确表达的需求」与「你自己的推测」——推测只可用于措辞与保守补充，绝不改变原文已明确的信息',\n  '3. 语义等价是底线：原文已明确的信息（动作对象、动作方向、数量、范围、禁止项、技术术语）必须与原文完全一致，不得替换、扩大、缩小或颠倒',\n  '',\n  '【项目事实优先（本模式核心）】',\n  '- 参考块含项目文档与代码事实（【项目文档参考】【相关代码参考】），以文档与代码为准，不得臆造接口、结构、文件名',\n  '- 优化结果使用软件工程专业词汇，可直接作为开发任务书 / 编码助手输入',\n  '- 文档 / 代码与输入意图冲突时，以输入意图为主，但不得编造不存在的实现细节；未明确处用「如无特别说明/默认」标注',\n  '- 完成后可输出【调整方案】（专业词汇替换与修订建议），帮助执行者理解优化逻辑',\n  '',\n  '【任务意图判断（本模板核心·开发向）】',\n  '1. 先判断语句实际想执行的开发任务：任务类型（实现 / 重构 / 修复 / 文档 / 测试 / 迁移）、涉及模块、交付形态（代码 / 任务单 / PR 描述 / 方案）',\n  '2. 把任务映射为工程大逻辑：功能→模块/接口、数据→结构/字段/类型、处理→算法/流程/边界、环境→依赖/配置/构建',\n  '3. 盘点「工程执行所必需的大逻辑与信息」——尤其「语句没说的、执行模型不知道会误判」的：任务边界（改哪里、不改哪里）、交付形态、涉及模块、必要默认值（未指定时）',\n  '4. 逐项对比原文与项目事实：已说（保留）、未说但必需（保守补充）——只补「缺失会导致执行模型误判」的大逻辑/信息',\n  '',\n  '【保守增量规则（红线）】',\n  '- 只补「大的逻辑与信息」：任务类型、对象范围、交付形态、关键边界、必要默认值——不补细节（具体数值、具体步骤、具体 API/技术方案、具体文件名/目录名）',\n  '- 不盲目扩充任务范围：不得新增原文没有的任务、目标、模块、功能',\n  '- 不臆造事实：不得编造项目文档/代码之外的接口、文件名、结构、依赖；补充内容必须由原文或项目事实可合理推断，或用「如无特别说明/默认」措辞标注',\n  '- **来源可回溯（防幻觉）**：每条补充都可回溯到原文或项目事实（文档/代码确认）——来自原文/项目事实的保留原意，推断的用「如无特别说明/默认」标注；无依据又无法合理推断的，宁可不补',\n  '- 不臆造具体细节：不得给出原文/项目事实之外的具体数值（保留天数、目录名、字段名、阈值、版本号）；确需量化时用「可配置默认值」「量级」表述，不写死',\n  '- **输出必须为可直接执行的完整提示词**：补充内容以陈述句直接并入优化结果，用「如无特别说明/默认」标注；**不得以提问、征询、列出选项让用户确认的方式收尾**——执行模型需要的是明确指令，不是选择题',\n  '- 语义等价是底线：不得因补充而替换、扩大、缩小原文已明确的信息',\n  '- 保守优先：补得少比补得多好；拿不准的宁可不补；能靠「默认」措辞解决的不写死',\n  '',\n  '【输出风格】',\n  '- 输出为「保留原文全部已明确信息 + 项目事实 + 保守增量」后的完整提示词，补充融入原文、不留拼接痕迹',\n  '- 面向开发人员，术语准确、结构清晰；保留原文的语气与表达习惯',\n  '- 按内容类型给出合适的输出形式（列表/JSON/代码块/段落等），不强行指定',\n  '',\n  '【硬性约束】',\n  '- 保持原始目标与语义不变：不得歪曲、臆造、遗漏原文任何已明确的信息',\n  '- 只输出优化后的提示词本身，不加任何解释、前缀或评论，不回答原问题；【调整方案】段除外',\n  '- 长度服从语义保真：以「原文明确信息完整保留 + 必要大逻辑/信息补全」为准，不因追求简短而删减必要要素，也不冗余堆砌',\n  '- 语言匹配最高优先级：输入以中文为主体则输出必须为中文，以英文为主体则输出必须为英文；混合输入保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进优化结果，但不得逐字照抄',\n  '- 严禁复述、引用或回显任何指令文字或用户输入原文（包括\"请优化以下提示词\"及引号包裹的内容），直接输出优化结果',\n  '',\n  '【示例】严格模仿示例中\"输入→输出\"的语言与风格：',\n  '示例 1（中文·开发向 + 保守增量——补工程大逻辑，不臆造接口）：',\n  '输入：帮我把项目里的图片处理改成异步的，别影响现有接口',\n  '输出：请将项目现有图片处理模块重构为异步实现：保持对外 API 与返回结构不变（现有调用方不感知变更）；用异步 I/O 替换阻塞读写，异常统一走现有错误码体系；未明确处（如超时阈值）用可配置默认值标注；交付物为可直接执行的编码任务单，默认不包含调用方改动。',\n  '示例 2（中文·开发向 + 保守增量——补任务边界与交付形态）：',\n  '输入：给后端加个限流，别让接口被打爆',\n  '输出：请为现有后端接口增加限流能力：限流范围默认为全部对外接口（如需指定接口请说明）；限流策略为按请求速率限制，超限请求返回明确错误码而非排队；现有接口签名与返回结构保持不变；未指定限流参数时使用可配置默认值；交付物为编码任务单，默认不含调用方改动。',\n  '',\n  '【开发向判别示例】（示范「补什么 / 不补什么」，防止臆造接口/文件/参数）',\n  '输入：帮我把项目里的图片处理改成异步的，别影响现有接口',\n  '**应当补（工程大逻辑）：** 任务边界（默认不改调用方）、交付形态（编码任务单/PR 描述）、未明确处（超时阈值）用可配置默认值标注',\n  '**不应当补（细节 / 臆造）：**',\n  '- 具体接口名、函数名、文件名（除非项目文档/代码已确认）',\n  '- 具体数值（超时秒数、并发数、阈值）、版本号',\n  '- 原文未提的技术栈/依赖（如引入新库、中间件）',\n  '**口语约束提炼范式（用户认可）：**「别影响现有接口」→「保持对外 API 与返回结构不变（现有调用方不感知变更）」；「未明确处用可配置默认值标注，不写死」。',\n].join('\\n');\n\nconst SYSTEM_INCREMENT_PUBLISH_PROMPT = [\n  '你是一名资深项目/游戏开发规划专家，精通需求工程（IEEE 29148 需求规格方法）与游戏设计文档（GDD）方法论。用户给出的是一句粗略想法或已有内容（可能是多轮补充后的现状），你的任务是在**保留原文全部已确认信息**的基础上，先理解用户实际想做什么任务，再对缺失的「大逻辑与信息」做**保守增量补充**——使规格可执行、不会让执行模型误判，但不补细节、不盲目扩大任务范围。',\n  '',\n  '【与默认模板的分工（先明确本模板定位）】',\n  '- 默认模板：把一句粗略想法生成完整九章规格（未明确处给出合理默认并标注）',\n  '- 本模板（增量模板）：在已有内容基础上，理解其实际想做的任务，只保守补充「该任务没说的、缺失会让执行模型误判」的大逻辑与信息——范围边界、交付形态、核心机制、验收维度；不补细节数值、不引入原文未提的新方向',\n  '',\n  '【增量补充规则】',\n  '1. **以原内容为完整基础**：保留原有全部已确认设计（目标、范围、技术选型、数值、架构、交互等），不得推翻、替换或重写',\n  '2. **任务意图判断**：先明确用户实际想做什么任务（游戏类型/软件类型/交付形态/目标用户），再判断执行此任务必须知道、但原内容没说的「大逻辑与信息」：',\n  '   - 交付形态：单文件 / 库 / 服务 / 原型（未指定 → 默认合理形态）',\n  '   - 范围边界：明确不做什么（未指定 → 给出合理默认边界）',\n  '   - 核心机制：玩法/功能核心循环（未指定 → 给出合理默认并标注）',\n  '   - 验收维度：可测试的验收方向（与第二/三/四章约束对应）',\n  '3. **逐章检查缺口**：按下方九章结构对照——缺失或含糊的「大逻辑/信息」补齐；**不补细节**（具体数值、具体方案名、具体清单数量）；数值只给量级（如 20×20×10）不必精确',\n  '4. **自洽优先**：补充内容不得与原设计冲突，不引入未确认的新方向；未明确处给出合理默认并标注「默认」',\n  '5. **来源追溯（防幻觉）**：每条补充标注来源——「已确认（来自原内容）」或「默认（合理推断）」；无原内容依据又无法合理推断的，宁可不补',\n  '6. **保留核对（输出前）**：逐条核对原内容每条已确认设计（目标、范围、技术选型、数值、架构、交互）都在九章中有对应且未被改变；漏改/被改 = 失败，回到对应章节修正',\n  '7. **需求表述纪律**：每条要求遵循单一陈述、义务用语（必须/不得/禁止）、可测试阈值（给量级）；不用无阈值的模糊形容词（与默认模板同款纪律）',\n  '8. **多轮扩充语义**：每一轮都必须输出**完整的九章规格**（在原文基础上），保持已确认设计、融入本次补充并细化',\n  '',\n  '【输出结构】（严格按以下九章，用用户主体语言输出）',\n  '一、目标概述与角色设定：保留原文目标，以「你是一个顶级的 XX 专家 / 技术美术（TA）」式角色设定开场（角色依据【场景判定】自动适配），随后给出：一句话目标 + 核心亮点/想实现的「感觉或反差」+ 核心体验闭环',\n  '二、需求范围与明确边界：明确「做什么 / 交付形态 / 明确不做什么」；用「绝对/必须/不得/禁止」级措辞写清硬边界',\n  '三、技术约束与架构：技术栈、依赖引入方式、架构方案（渲染管线、合批策略、后处理管线、材质体系、数据模型与模块划分）、性能与兼容性约束——架构层写实具体到方案名级别，数值给量级',\n  '四、核心功能要求：分维度逐条「必须」级要求（机制/视觉/材质/光照/音效/交互），每条附【设计意图】说明「为什么这样做」；**每条要求遵循【增量补充规则】第 7 条需求表述纪律**',\n  '五、场景与内容设计：具体内容清单（场景规模量级、物体/关卡/功能清单、资源策略、代码生成策略）',\n  '六、交互与界面：操作方式、初始视角、界面布局、反馈动效',\n  '七、扩展方向（带边界）：可选扩展方向逐一给出，并强制声明「扩展必须沿用既有体系/尺度/风格，不破坏闭合交付」',\n  '八、交付与限制：交付物清单（完整闭合、可直接运行）；禁止 TODO、占位实现或要求用户补齐核心算法；代码注释语言；输出格式要求',\n  '九、交付验收清单：逐条可勾选的验收项，对应第二/三/四章约束（可测试、不写空话）',\n  '',\n  '【场景适配】',\n  '- 系统按用户输入自动判定场景，并注入「【场景判定】本次场景判定：game/software/generic」行；未注入判定行时按默认九章输出，不追加场景侧重',\n  '- 【场景判定】为 game 时：三、技术约束与架构侧重渲染/表现方案；五、场景与内容设计含玩法循环、数值与经济量级',\n  '- 【场景判定】为 software 时：三、技术约束与架构侧重系统架构（模块划分、数据流、接口）；五、场景与内容设计含功能清单与数据模型',\n  '',\n  '【方案自评判定】（输出九章规格后必须追加以下自评块，不改变九章框架；以【方案自评】开头，按一~四逐项输出）',\n  '一、一致性核对：用户已明确需求逐条是否都有章节覆盖？缺项列出。',\n  '二、完整性核对：九章是否全部展开？缺章列出。',\n  '三、保守性核对：补充内容是否都属于「缺失会导致执行模型误判的大逻辑/信息」？是否存在补细节、扩范围、引入未确认新方向的条目？列出。',\n  '四、判定结论：【保留】（全部通过，可交付）或【调整】（列出差距项 + 调整方向，并在「调整建议」小节给出 ≤5 条修订要点）。',\n  '锚点规则（防自嗨）：任一「用户明确需求未覆盖」「九章缺章」或「补充超出保守范围」→ 必须判【调整】。',\n  '【自评段豁免条款】：自评段不受「不加解释/严禁回显」红线约束——允许概括引用用户需求点以核对覆盖，禁止逐字回显输入原文；其余正文仍严守红线。',\n  '',\n  '【保守增量判别示例】（示范「补什么 / 不补什么」，防止把增量做成反问或细节堆砌）',\n  '输入（已有内容草稿）：做一个 2D 纸牌游戏，要支持拖拽出牌。已完成：单人接龙模式、基础 UI。希望补充：让界面更美观，加入音效。',\n  '**增量应当补（大逻辑/信息）：**',\n  '- 交付形态：默认给出合理形态并标注（如「默认沿用原技术栈；原技术栈未明确 → 默认合理默认」）',\n  '- 范围边界：明确不做什么（如「禁止更改核心规则、禁止移除已有拖拽逻辑、除非已明确不自行扩展新模式」）',\n  '- 验收维度：可测方向（如「界面美化必须覆盖全部已有界面」「音效必须覆盖核心交互事件」）',\n  '**增量不应当补（细节 / 扩范围）：**',\n  '- 具体数值（配色色值、字体大小、音频格式、具体帧率指标）',\n  '- 具体方案名/引擎细节（若原文未提）',\n  '- 原文未提的新功能（如计分系统、联机模式、关卡系统）',\n  '**口语约束提炼范式（用户认可的示例）：**「让界面更美观」→「界面美化必须覆盖所有已有界面，风格统一，视觉反馈克制不干扰操作」；「加入音效」→「音效系统必须覆盖全部核心交互事件，音量可调，不依赖外部运行时下载」——把口语想法提炼成明确、具体、可执行、无歧义的需求陈述。',\n  '',\n  '【硬性约束】',\n  '- 不反问用户：未明确处给出合理默认并标注「默认」',\n  '- 严禁回显、引用或复述输入原文（包括已有规格内容），直接输出补充完善后的完整九章规格',\n  '- 顺序与公式绝对精确：乘算倍增非加算',\n  '- 语言匹配：以用户主体语言输出，保留原文中的术语与专有名词',\n  '- 若存在【相关会话参考】/【项目文档参考】/【参考上下文】，将其中与当前任务直接相关的明确需求、约束、默认值吸收进对应章节，但不得逐字照抄',\n].join('\\n');\n\nconst RELEVANCE_PROMPT = [\n  '你是一个会话关联性判定器。判断给定的「历史会话片段」与「当前用户输入」是否相关。',\n  '',\n  '【关联的定义】',\n  '历史片段与当前输入涉及相同或直接相关的主题、任务、对象、技术或上下文，能够为优化当前输入提供有效参考——例如：同一项目的讨论、同一提示词的迭代过程、与当前输入直接相关的需求说明或技术背景。',\n  '',\n  '【不关联的定义】',\n  '历史片段与当前输入主题无关——例如：无关的闲聊、其他任务的讨论、与当前输入没有任何共同点的内容。',\n  '',\n  '【判定规则】',\n  '1. 只依据历史片段与当前输入的实际内容判断，不臆测不存在的信息。',\n  '2. 历史片段为空或仅剩截断残片时，判定为不关联。',\n  '3. 宁可漏判（不关联），不可错判（把无关内容当作参考）。',\n  '',\n  '【输出格式】',\n  '只输出一个 JSON 对象，不要输出任何其他内容：',\n  '{\"related\": true 或 false, \"reason\": \"一句话中文理由（不超过 30 字）\"}',\n  '',\n  '【输入】',\n  '历史会话片段：',\n  '\"\"\"',\n  '{history}',\n  '\"\"\"',\n  '',\n  '当前用户输入：',\n  '\"\"\"',\n  '{current}',\n  '\"\"\"',\n].join('\\n');\n\nconst SMART_TAIL_PROMPT = [\n  '你是一名资深软件工程专家。请在完成提示词优化后，额外输出【调整方案】分析块。',\n  '',\n  '【调整方案要求】（严格按以下逻辑，不改变优化结果本身）',\n  '一、可优化点分析：对照原始提示词，逐条列出表述不够准确、含糊、可执行性弱的地方。',\n  '二、专业词汇替换：将可用软件开发领域更专业、更精确的词汇/句式替换的表述列出',\n  '   （如「把文件看看」→「对指定路径执行只读检查」；「改一下」→「实施增量修改」；',\n  '    「弄好」→「完成实现并通过验证」）。替换必须保持语义等价，不得改变原意。',\n  '三、调整建议：给出 ≤5 条修订要点，每条 = 原文表述 → 专业表述 → 理由。',\n  '',\n  '【输出格式】',\n  '先输出优化后的提示词本身（遵守系统提示词的全部规则），然后另起一行输出：',\n  '【调整方案】',\n  '一、可优化点分析：…',\n  '二、专业词汇替换：…',\n  '三、调整建议：…',\n].join('\\n');\n\nconst DEV_INTENT_PROMPT = [\n  '你是一个提示词意图判定器。判断给定的「当前用户输入（提示词）」是否表达**项目开发意向**。',\n  '',\n  '【项目开发意向的定义】',\n  '输入表达了对某个项目/软件/游戏/系统进行开发、实现、重构、修改、优化、调试、扩展、集成、部署等意图——例如：',\n  '- 「帮我开发一个用户管理系统」',\n  '- 「优化一下这个登录功能的实现」',\n  '- 「重构这段代码」',\n  '- 「给我的项目加一个功能」',\n  '',\n  '【非项目开发意向的定义】',\n  '输入不涉及具体项目开发——例如：',\n  '- 纯粹的写作/翻译/文案优化',\n  '- 通用知识问答',\n  '- 与代码/项目无关的日常请求',\n  '',\n  '【判定规则】',\n  '1. 输入明确指向项目/代码/系统开发相关的任务 → true。',\n  '2. 输入含糊或无法确定是否涉及项目开发 → false（宁停勿滥）。',\n  '3. 只依据输入内容本身与给定的会话参考判断，不臆测。',\n  '',\n  '【输出格式】',\n  '只输出一个 JSON 对象，不要输出任何其他内容：',\n  '{\"isDevIntent\": true 或 false, \"reason\": \"一句话中文理由（不超过 30 字）\"}',\n  '',\n  '【输入】',\n  '当前用户输入：',\n  '\"\"\"',\n  '{prompt}',\n  '\"\"\"',\n  '',\n  '相关会话参考（可能为空）：',\n  '\"\"\"',\n  '{session}',\n  '\"\"\"',\n].join('\\n');\n\nconst DOC_ANALYSIS_PROMPT = [\n  '你是一个项目文档分析器。根据给定的「候选 .md 文档清单与内容摘要」、「当前用户输入（提示词）」与「相关会话参考」，执行两项任务：',\n  '',\n  '【任务一：检索相关参考信息】',\n  '从候选 .md 文档中挑出与提示词**相关**的文档（主题/内容与提示词涉及的项目、功能、技术直接相关），并为每个相关文档提取一段要点摘要（≤200 字符）。无关文档不选。',\n  '',\n  '【任务二：分析项目地图结构】',\n  '判断这些相关 .md 文档（以及候选清单整体）中，是否存在**项目地图或类似的可快速定位代码文档位置的结构**——例如：',\n  '- README 中的目录树 / 模块结构说明',\n  '- docs/map、INDEX、文档索引、导航文件',\n  '- 文档中列出的源码目录结构 / 模块路径指引',\n  '',\n  '【输出格式】',\n  '只输出一个 JSON 对象，不要输出任何其他内容：',\n  '{',\n  '  \"relatedDocs\": [{\"path\": \"文档路径\", \"excerpt\": \"要点摘要（≤200字）\"}],',\n  '  \"hasProjectMap\": true 或 false,',\n  '  \"codePaths\": [\"文档中明确指向的代码目录/路径（如 src/、packages/core/，无则空数组）\"],',\n  '  \"reason\": \"一句话中文理由（不超过 40 字）\"',\n  '}',\n  '',\n  '【输入】',\n  '候选 .md 文档清单与内容摘要：',\n  '\"\"\"',\n  '{docs}',\n  '\"\"\"',\n  '',\n  '当前用户输入：',\n  '\"\"\"',\n  '{prompt}',\n  '\"\"\"',\n  '',\n  '相关会话参考（可能为空）：',\n  '\"\"\"',\n  '{session}',\n  '\"\"\"',\n].join('\\n');\n\nconst WEBSEARCH_PLAN_PROMPT = [\n  '你负责为一个「项目/游戏开发规格生成」流程规划网络检索主题。给定用户的最新想法、此前各轮已检索主题与要点摘要、场景判定，输出 2~3 个**差异化**检索主题（避开已检索主题），供后续逐个搜索并注入【网络参考】。',\n  '',\n  '【输入】',\n  '- 用户最新想法：{text}',\n  '- 已获取网络要点（此前轮次检索结果摘要，含已检索主题清单）：{memo}',\n  '- 场景判定：{scenario}',\n  '',\n  '【输出要求】',\n  '- 输出 2~3 个检索主题，覆盖用户想法中最需要业界参考的方面（技术方案/同类实现/素材与资源来源/市场参考等）',\n  '- 与已检索主题不重复；若已有要点已覆盖充分，可只输出 1 个最关键缺口主题',\n  '- 每个主题给出：query（可直接用于搜索的中文短语，≤20 字）+ note（一句检索目的）',\n  '- 仅输出 JSON，格式：{\"topics\":[{\"query\":\"…\",\"note\":\"…\"}]}',\n  '- 除该 JSON 外不得输出任何内容（无解释、无前言、无代码块标记）',\n].join('\\n');\n\nconst CONTINUE_PROMPT = [\n  '【继续优化模式】',\n  '- 用户正在修改上一轮优化结果，本次优化以「本轮修改」为主要方向，不要重新从零优化。',\n  '- 保留未修改部分的语义与结构，只围绕新增/删除/调整点完善。',\n  '- 输出完整更新后的提示词，禁止输出 diff、片段或仅回应修改。',\n].join('\\n');\n// ==PROMPTS-END==\n\n// @dsh-pure-inject\n\n// ================= V2 上下文感知优化 · 运行时（阶段 A/B/C） =================\n// v2.0.0 方案 §3：阶段 A 任务进度（smart LLM / basic 规则）→ 阶段 B 相关性检索\n// （工作区文件 + 会话事件）→ 阶段 C 预算组装注入。各阶段独立降级，不阻断优化。\n// v2.4.6：TASK_ANALYSIS_PROMPT / CONTEXT_GUARD 已外置 prompts/*.md（见生成标记区）。\n\nconst V2_WORKSPACE_IGNORE_DIRS = new Set(['node_modules', '.git', 'dist', 'build', '.venv', 'venv', '__pycache__', '.next', '.cache', 'coverage', 'target', '.idea', '.vscode']);\n\n// 阶段 A：任务进度理解（表驱动 phaseA：none 跳过 / rule 正则 / llm 智能（失败降级 rule）/ memory 读记忆对）\n// 返回值：{ progress, mode }；mode: 'smart'|'rule'|'memory'|'none'\nasync function v2ResolveProgress(services, historyText, cfg) {\n  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];\n  if (row.phaseA === 'llm' && services.llm && services.chain && services.chain.length > 0 && historyText.trim() !== '') {\n    const entry = services.chain[0];\n    let timedOut = false;\n    const timer = services.timer.timeout(() => { timedOut = true; }, V2_PROGRESS_TIMEOUT_MS);\n    try {\n      const stream = services.llm.stream({\n        provider: entry.provider,\n        model: entry.model,\n        // v3.0p 审查（超时/耗时匹配）：阶段 A 任务分析剥离 reasoningEffort（同 judge 策略）\n        maxTokens: V2_PROGRESS_MAX_TOKENS,\n        system: TASK_ANALYSIS_PROMPT,\n        messages: [{\n          id: 'enhance-task-progress',\n          role: 'user',\n          content: [{ type: 'text', text: historyText.slice(0, V2_HISTORY_MAX_CHARS) }],\n          source: { kind: 'user' },\n        }],\n      });\n      const iterator = stream[Symbol.asyncIterator]();\n      const result = await collectStream(iterator, V2_PROGRESS_OUTPUT_LIMIT);\n      if (!timedOut && result.kind === 'ok') {\n        const parsed = parseTaskProgress(result.text);\n        if (parsed) {\n          hlog('[enhance] v2 smart progress ok');\n          return { progress: parsed, mode: 'smart' };\n        }\n        hlog('[enhance] v2 smart progress bad-json');\n      } else {\n        hlog('[enhance] v2 smart progress ' + (timedOut ? 'timeout' : 'empty'));\n      }\n    } catch (e) {\n      hlog('[enhance] v2 smart progress failed', e && e.message ? e.message : e);\n    } finally {\n      timer();\n    }\n  }\n  // rule 规则提取（零成本；无历史时返回空 focus）——phaseA: rule / llm 降级 / memory 无记忆时兜底\n  const focus = inferFocusRules(historyText);\n  if (focus.length > 0) return { progress: { focus }, mode: 'rule' };\n  return { progress: null, mode: 'rule' };\n}\n\n// 阶段 B：工作区文件检索（fs 扫描 + 名称/内容命中 → Top-3 摘要；2s 超时降级）\n// v2.0.7：fs 契约修正——listDir/readText 接收 FsTarget（resolve 产出），条目 shape 为\n// {name, type:'file'|'directory', target}；不再传字符串路径。\nasync function v2SearchWorkspace(services, keywords, cfg) {\n  const fsSvc = services.fs;\n  const root = services.sandboxPolicy && services.sandboxPolicy.workspaceRoot;\n  if (!fsSvc || !root || typeof fsSvc.listDir !== 'function' || typeof fsSvc.readText !== 'function' || typeof fsSvc.resolve !== 'function') return [];\n  // 表驱动：phaseB 非 file+event 跳过；扫描上限按 scanLimit（by-budget 查联动表 / fixed 固定）\n  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];\n  if (row.phaseB !== 'file+event') return [];\n  const lim = resolveScanLimit(cfg.mode, cfg.context.budgetChars);\n  const depth = lim.depth;\n  const maxFiles = lim.maxFiles;\n  let aborted = false;\n  const timer = services.timer.timeout(() => { aborted = true; }, V2_WORKSPACE_TIMEOUT_MS);\n  try {\n    let rootTarget;\n    try {\n      rootTarget = await fsSvc.resolve(root);\n    } catch (e) {\n      hlog('[enhance] v2 workspace resolve-root failed', e && e.message ? e.message : e);\n      return [];\n    }\n    const files = [];\n    const walk = async (target, rel, level) => {\n      if (aborted || files.length >= SCAN_FILE_LIST_MAX || level > depth) return;\n      let entries;\n      try {\n        entries = await fsSvc.listDir(target);\n      } catch (e) { return; }\n      for (const en of entries || []) {\n        if (aborted) return;\n        const name = en && en.name;\n        if (!name) continue;\n        if (V2_WORKSPACE_IGNORE_DIRS.has(name)) continue;\n        const relPath = rel ? rel + '/' + name : name;\n        if (en.type === 'directory') {\n          await walk(en.target, relPath, level + 1);\n        } else if (en.type === 'file') {\n          files.push(relPath);\n        }\n      }\n    };\n    await walk(rootTarget, '', 1);\n    if (aborted) { hlog('[enhance] v2 workspace scan timeout'); return []; }\n    hlog('[enhance] v2 workspace scanned files=' + files.length);\n    // 名称匹配 → 候选；v2.7.0：名称 0 命中时内容兜底（中文场景名称匹配几乎必然落空——\n    // 中文关键词 vs 英文文件名；降级取前 N 个文本文件按内容关键词命中，救活\n    // 「文件内容相关但文件名无关」场景；读取受 V2_WORKSPACE_TIMEOUT_MS 总超时保护）\n    const candidates = rankFiles(files, keywords, 10).map((c) => c.path);\n    if (candidates.length === 0) {\n      const textRe = /\\.(?:md|txt|py|ts|js|tsx|jsx|json|yaml|yml|toml|css|html|go|rs|java|cpp|c|h|sh|sql|vue)$/i;\n      // 文档类（md/txt）优先——描述性内容最可能命中主题词\n      const docFirst = files.slice().sort((a, b) => {\n        const da = /\\.(?:md|txt)$/i.test(a) ? 0 : 1;\n        const db = /\\.(?:md|txt)$/i.test(b) ? 0 : 1;\n        return da - db;\n      });\n      const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);\n      const contentScored = [];\n      let scanned = 0;\n      for (const rel of docFirst) {\n        if (aborted || scanned >= CONTENT_FALLBACK_SCAN) break;\n        if (!textRe.test(rel) || shouldIgnoreFile(rel)) continue;\n        scanned++;\n        let text = '';\n        try {\n          const target = await fsSvc.resolve(rel, { cwd: root });\n          text = await fsSvc.readText(target);\n        } catch (e) { continue; } // 只读权限/读取失败 → 跳过该文件\n        const lines = text.split('\\n');\n        let contentHits = 0;\n        for (const ln of lines) {\n          if (kws.some((k) => ln.toLowerCase().includes(k.toLowerCase()))) contentHits++;\n          if (contentHits >= 8) break;\n        }\n        if (contentHits > 0) contentScored.push({ path: rel, lines, contentHits });\n      }\n      hlog('[enhance] v2 workspace content-fallback scanned=' + scanned + ' hits=' + contentScored.length + ' kws=' + JSON.stringify(keywords));\n      if (contentScored.length === 0) {\n        hlog('[enhance] v2 workspace no-name-match files=' + files.length + ' kws=' + JSON.stringify(keywords));\n        return [];\n      }\n      contentScored.sort((a, b) => b.contentHits - a.contentHits);\n      const top = contentScored.slice(0, maxFiles);\n      return top.map((f) => ({ path: f.path, snippet: snippetFromLines(f.lines, keywords, SNIPPET_BUDGET) }));\n    }\n    // 内容命中加分 → 排序 Top-maxFiles\n    const scored = [];\n    for (const rel of candidates) {\n      if (aborted) break;\n      if (shouldIgnoreFile(rel)) continue;\n      let text = '';\n      try {\n        const target = await fsSvc.resolve(rel, { cwd: root });\n        text = await fsSvc.readText(target);\n      } catch (e) { continue; } // 只读权限/读取失败 → 跳过该文件\n      const lines = text.split('\\n');\n      let contentHits = 0;\n      const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);\n      for (const ln of lines) {\n        if (kws.some((k) => ln.toLowerCase().includes(k.toLowerCase()))) contentHits++;\n        if (contentHits >= 8) break;\n      }\n      if (contentHits > 0) scored.push({ path: rel, lines, contentHits });\n    }\n    if (scored.length === 0) {\n      hlog('[enhance] v2 workspace no-content-match candidates=' + candidates.length + ' kws=' + JSON.stringify(keywords));\n      return [];\n    }\n    scored.sort((a, b) => b.contentHits - a.contentHits);\n    const top = scored.slice(0, maxFiles);\n    return top.map((f) => ({ path: f.path, snippet: snippetFromLines(f.lines, keywords, SNIPPET_BUDGET) }));\n  } finally {\n    timer();\n  }\n}\n\n// 阶段 B3：会话事件检索（增强；searchEvents 契约：{sessionId,query,limit} → {items:[{snippet}]}；失败跳过）\nasync function v2SearchEvents(services, sessionId, keywords, cfg) {\n  const sq = services.sessionQuery;\n  const kws = (keywords || []).filter((k) => typeof k === 'string' && k.trim() !== '');\n  // 表驱动：phaseB 非 file+event 跳过\n  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];\n  if (row.phaseB !== 'file+event') return [];\n  if (!sq || typeof sq.searchEvents !== 'function' || kws.length === 0) {\n    hlog('[enhance] v2 searchEvents skipped kws=' + kws.length);\n    return [];\n  }\n  // v3.0p 审查（超时/耗时匹配）：searchEvents 补超时保护（10s，超时/失败 → [] 不阻断）\n  let timedOut = false;\n  const timer = services.timer.timeout(() => { timedOut = true; }, V2_SEARCH_EVENTS_TIMEOUT_MS);\n  try {\n    const page = await sq.searchEvents({ sessionId, query: kws.join(' '), limit: 3 });\n    if (timedOut) { hlog('[enhance] v2 searchEvents timeout'); return []; }\n    const hits = page && Array.isArray(page.items) ? page.items : [];\n    hlog('[enhance] v2 searchEvents kws=' + JSON.stringify(kws) + ' hits=' + hits.length);\n    if (hits.length === 0) return [];\n    return hits.slice(0, 3).map((h) => {\n      const txt = h && (typeof h.snippet === 'string' ? h.snippet : (typeof h.text === 'string' ? h.text : ''));\n      return txt ? txt.slice(0, 300) : '';\n    }).filter(Boolean);\n  } catch (e) {\n    hlog('[enhance] v2 searchEvents failed', e && e.message ? e.message : e);\n    return []; // 服务缺失/请求形状不符/失败 → 跳过事件段\n  } finally {\n    timer();\n  }\n}\n\n// 阶段 A/B/C 汇总：返回 { block, log }（全部不可用 → { block: '', log: 'none' }）\n// v2.2（§6.5）：4 模式管道（base/lite 空块 / standard/smart 检索）。\n// v2.6.1（记忆链）：记忆不再作为文本块叠加（改由 enhance 入口以真多轮消息注入，\n// 见 buildChatMessages），模式块独享预算；log 仅含模式块口径（记忆见入口 memory 日志）。\n// v2.3（§7.3）：onStage 回调（由 enhance handler 注入，写 pending 记录的 stage 字段；\n// 纯函数本体不接触模块状态，回调缺省为 no-op 保持 PURE 区段可切片）。\nasync function buildV2ContextBlock(services, sessionId, text, cfg, onStage) {\n  const mark = typeof onStage === 'function' ? onStage : () => {};\n  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];\n  const budget = cfg.context.budgetChars || 0;\n  // ===== 模式管道（base/lite：phaseB='none' 无检索 → 空模式块）=====\n  let modeBlock = '';\n  let modeLog = 'none';\n  // v3.0p（publish 多步检索）：web 段结果透出（跨轮记忆用；无检索时为空）\n  let webTopics = [];\n  let webMemoText = '';\n  if (row.phaseC === 'inject') {\n    // 历史 + 阶段A + 阶段B\n    let events = [];\n    let historyText = '';\n    const sq = services.sessionQuery;\n    if (sq && typeof sq.listEvents === 'function' && typeof sq.filterEvents === 'function') {\n      try {\n        mark(STAGE_HISTORY);\n        // v3.1.3（用户需求·仅结论参考）：同 v3 路径——readSurface 块级结论提取，旧路径兜底\n        if (typeof sq.readSurface === 'function') {\n          const surface = await sq.readSurface(sessionId);\n          events = extractHistoryConclusions(surface && surface.events);\n        } else {\n          const records = await sq.listEvents(sessionId);\n          // 尾部反向找最近的消息事件 seq（listEvents 升序，无文本；seq 用于 filterEvents 范围过滤）\n          const msgSeqs = [];\n          for (let i = records.length - 1; i >= 0 && msgSeqs.length < V2_MSG_SEQ_SCAN; i--) {\n            const r = records[i];\n            const t = String(r && r.type || '');\n            if (t === 'user/message' || t === 'assistant/message') msgSeqs.push(r && r.seq);\n          }\n          if (msgSeqs.length > 0) {\n            const minSeq = msgSeqs[msgSeqs.length - 1];\n            const docs = await sq.filterEvents(sessionId, [{ kind: 'seq', from: minSeq }]);\n            events = extractHistory(docs, V2_HISTORY_LIMIT);\n          }\n        }\n        historyText = events.map((e) => (e.type === 'user' ? '[用户] ' : '[助手] ') + e.text).join('\\n');\n        hlog('[enhance] v2 history events=' + events.length + ' chars=' + historyText.length + (typeof sq.readSurface === 'function' ? ' conclusion-only' : ''));\n      } catch (e) {\n        hlog('[enhance] v2 history failed', e && e.message ? e.message : e);\n      }\n    } else {\n      hlog('[enhance] v2 sessionQuery unavailable');\n    }\n    const root = services.sandboxPolicy && services.sandboxPolicy.workspaceRoot;\n    hlog('[enhance] v2 workspaceRoot=' + (root || '(none)') + ' fs=' + (services.fs ? 'yes' : 'no'));\n    // 阶段 A（表驱动 phaseA：llm 智能 / rule 正则 / none 跳过）\n    mark(STAGE_ANALYZE);\n    const { progress, mode } = await v2ResolveProgress(services, historyText, cfg);\n    // 阶段 B（表驱动 phaseB：file+event 全量 / none 跳过）\n    const focus = progress && Array.isArray(progress.focus) ? progress.focus : [];\n    const keywords = extractKeywords(text, focus);\n    mark(STAGE_FILES, { key: 'scan' });\n    const files = await v2SearchWorkspace(services, keywords, cfg);\n    mark(STAGE_EVENTS);\n    const eventsHits = await v2SearchEvents(services, sessionId, keywords, cfg);\n    // 阶段 C（inject）：模式块独享预算（记忆链不占文本块）\n    modeBlock = buildContextBlock(progress, files, eventsHits, budget);\n    // v2.7.0（一键发布 · 网络检索）：publish 专属——依据草稿主题词 + 记忆链 delta\n    // 改动方向构造检索词，经 ctx.web 搜索同类项目结构参考，注入模式块（预算余量内）。\n    // 独立超时/降级：搜索失败/服务缺失 → 跳过，不阻断规格生成。\n    let webLog = 'none';\n    if (cfg.mode === 'publish' && budget > 0) {\n      mark(STAGE_FILES); // 复用 files 阶段标记（检索类）\n      // v3.0p（publish 多步检索）：跨轮要点回注——历史【已获取网络参考】前置（预算内），\n      // 让模型「记住」此前检索到的信息，只补新缺口（配合 publishWebMemo 会话级记忆）\n      if (services.webMemo) {\n        const memoBlock = '【已获取网络参考】\\n' + String(services.webMemo).slice(0, WEB_MEMO_MAX);\n        modeBlock = modeBlock ? modeBlock + '\\n\\n' + memoBlock : memoBlock;\n      }\n      // v3.0p（publish 多步检索）：LLM 规划的差异化主题逐主题搜索（services.webPlan 非空时）；\n      // 无规划 / 规划失败 → 降级旧单 query 路径（buildWebQuery + 场景方向词，行为不变）\n      const web = services.web;\n      const planQueries = Array.isArray(services.webPlan) && services.webPlan.length > 0\n        ? services.webPlan.map((t) => String(t && t.query || '').trim()).filter((q) => q !== '').slice(0, 3)\n        : [];\n      const queries = planQueries.length > 0 ? planQueries : [null];\n      const topicLogs = [];\n      if (web && typeof web.search === 'function') {\n        const refParts = [];\n        const memoParts = [];\n        for (let qi = 0; qi < queries.length; qi++) {\n          const q = queries[qi];\n          let query = q;\n          if (query === null) {\n            query = buildWebQuery(text, keywords, services.delta || null);\n            if (services.scenario === 'game') query = (query ? query + ' 游戏实现' : '游戏实现');\n            else if (services.scenario === 'software') query = (query ? query + ' 软件架构' : '软件架构');\n          }\n          // v3.0r（细粒度进度反馈）：逐主题搜索进度（detailKey=search，client 渲染「正在搜索 i/n：query」）\n          mark(STAGE_FILES, { key: 'search', args: { query }, step: qi + 1, total: queries.length });\n          let timedOut = false;\n          const timer = services.timer.timeout(() => { timedOut = true; }, WEB_SEARCH_TIMEOUT_MS);\n          try {\n            const res = await web.search({ query, maxResults: WEB_SEARCH_MAX_RESULTS });\n            if (!timedOut && res && Array.isArray(res.sources) && res.sources.length > 0) {\n              const lines = res.sources.slice(0, WEB_SEARCH_MAX_RESULTS).map((s) => {\n                const title = s && s.title ? String(s.title) : '';\n                const url = s && s.url ? String(s.url) : '';\n                const summary = s && s.summary ? String(s.summary).slice(0, 200) : '';\n                return '- ' + title + (url ? ' (' + url + ')' : '') + (summary ? '\\n  ' + summary : '');\n              }).join('\\n');\n              refParts.push('### 检索主题：' + query + '\\n' + lines);\n              memoParts.push('『' + query + '』：' + res.sources.slice(0, 2).map((s) => String(s && s.title || '') + (s && s.summary ? '——' + String(s.summary).slice(0, 60) : '')).join('；'));\n              topicLogs.push({ query, hits: res.sources.length });\n            } else {\n              topicLogs.push({ query, hits: timedOut ? -2 : 0 });\n            }\n          } catch (e) {\n            topicLogs.push({ query, hits: -1 });\n          } finally {\n            timer();\n          }\n        }\n        const refText = refParts.join('\\n\\n');\n        if (refText) {\n          const webBlock = '【网络参考】\\n' + refText.slice(0, Math.min(WEB_REF_MAX, Math.max(0, budget - modeBlock.length)));\n          if (webBlock.length > 20) {\n            modeBlock = modeBlock ? modeBlock + '\\n\\n' + webBlock : webBlock;\n            webLog = 'web=' + topicLogs.filter((t) => t.hits > 0).length + '/' + topicLogs.length + ' chars=' + webBlock.length;\n          } else {\n            webLog = 'web=0';\n          }\n        } else {\n          webLog = 'web=0';\n        }\n        webTopics = topicLogs;\n        webMemoText = memoParts.join('\\n').slice(0, WEB_MEMO_MAX);\n      } else {\n        webLog = 'web=none';\n      }\n      hlog('[enhance] v2 web ' + webLog + ' queries=' + topicLogs.map((t) => t.query + ':' + t.hits).join('|').slice(0, 200));\n    }    modeLog = modeBlock === '' ? 'none' : (mode + ' files=' + files.length + ' events=' + eventsHits.length + (webLog !== 'none' ? ' ' + webLog : '') + ' chars=' + modeBlock.length);\n  }\n  // ===== 汇总（记忆链由 enhance 入口以多轮消息注入，不占文本块）=====\n  mark(STAGE_CONTEXT);\n  return { block: modeBlock, log: modeBlock === '' ? 'none' : modeLog, webTopics, webMemoText };\n}\n\nfunction selfState(reference) {\n  const status = reference.latestRun && reference.latestRun.status;\n  if (status === 'awaiting-approval') return 'awaiting-approval';\n  if (status === 'client-pending' || status === 'starting-host') return 'client-pending';\n  if (status === 'failed' || status === 'rejected' || status === 'cancelled') return 'failed';\n  if (status === 'waiting') return 'waiting';\n  if (status === 'running') return 'running';\n  if (reference.activeRun !== undefined) return 'running';\n  return reference.currentPackageId === undefined ? 'defined' : 'stopped';\n}\n\nfunction summarize(reference) {\n  const latest = reference.latestRun;\n  const state = selfState(reference);\n  return {\n    pluginId: String(reference.pluginId),\n    name: reference.name,\n    state,\n    // v2.4.3-fix：透传每包半部完整性——client 版本下拉据此禁用残缺包（防误切致 UI 消失）\n    ...(reference.packages ? { packages: reference.packages.map((p) => ({ packageId: String(p.packageId), name: p.name, purpose: p.purpose || '', hasHostHalf: p.hasHostHalf === true, hasClientHalf: p.hasClientHalf === true })) } : { packages: [] }),\n    ...(reference.currentPackageId === undefined ? {} : { currentPackageId: String(reference.currentPackageId) }),\n    ...(reference.nextPackageId === undefined ? {} : { nextPackageId: String(reference.nextPackageId) }),\n    ...(reference.activeRun === undefined ? {} : { activeRun: { pluginRunId: String(reference.activeRun.pluginRunId), packageId: String(reference.activeRun.packageId) } }),\n    ...(latest && latest.status === 'awaiting-approval' ? { pendingApproval: { pluginRunId: String(latest.pluginRunId), packageId: String(latest.packageId), mode: latest.mode } } : {}),\n  };\n}\n\nreturn {\n  inject: ['timer'],\n  apply(ctx) {\n    const llm = ctx.get('llm');\n    const pending = new Map();\n    // v2.8.0（一键发布 · 场景路由）：会话级场景缓存（sessionId → game/software/generic）。\n    // 首轮判定写入、后续轮读取不重判（场景决定九章骨架，翻转会推翻已确认设计）；\n    // 生命周期 = 插件进程，进程重启后缓存 miss → 用记忆链最早轮输入兜底判定（enhance 内判定源规则）\n    const publishScenarioCache = new Map();\n    // v3.0p（publish 多步检索）：会话级网络检索记忆（sessionId → {topics[], memo}）。\n    // topics = 已检索主题（去重，≤WEB_MEMO_TOPICS_MAX）；memo = 已获取要点摘要（≤WEB_MEMO_MAX，\n    // 跨轮以【已获取网络参考】回注，让模型记住已查信息、只补新缺口）。\n    // 生命周期 = 插件进程（同 publishScenarioCache）。\n    const publishWebMemo = new Map();\n\n    function requestKey(sessionId, seq) {\n      return String(sessionId) + ':' + String(seq);\n    }\n\n    function markAndAbort(key, flag) {\n      const rec = pending.get(key);\n      if (!rec) return;\n      rec[flag] = true;\n      if (rec.iterator && typeof rec.iterator.return === 'function') {\n        try { rec.iterator.return(); } catch (e) { /* 忽略 */ }\n      }\n    }\n\n    function resolveAgent(sessionId) {\n      const agents = ctx.get('agents');\n      if (!agents || typeof agents.get !== 'function') return null;\n      return agents.get(sessionId) || null;\n    }\n\n    harness.handle('models/list', async () => {\n      const llmService = ctx.get('llm');\n      if (!llmService || typeof llmService.listProviders !== 'function') {\n        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };\n      }\n      try {\n        const providers = llmService.listProviders();\n        const out = [];\n        for (const p of providers) {\n          let models = [];\n          try {\n            const list = await llmService.listModels(p.id);\n            models = (list || []).map((m) => ({ id: m.id, name: m.name || m.id }));\n          } catch (e) { models = []; }\n          out.push({ provider: p.id, name: p.name, models });\n        }\n        return { ok: true, providers: out };\n      } catch (e) {\n        herr('[enhance] models/list failed', e);\n        return { ok: false, code: 'MODELS_FAILED', message: String(e && e.message ? e.message : e) };\n      }\n    });\n\n    harness.handle('models/resolve', async (args) => {\n      const provider = args && typeof args.provider === 'string' ? args.provider : '';\n      const model = args && typeof args.model === 'string' ? args.model : '';\n      const llmService = ctx.get('llm');\n      if (!llmService || typeof llmService.resolveModelInfo !== 'function') {\n        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };\n      }\n      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };\n      try {\n        // v21（P1-4）：走 TTL 缓存，避免重复适配器能力查询\n        // F1（配置卫生）：noCache 旁路 TTL——client effort 纠偏场景需要新鲜能力表\n        const info = await resolveModelInfoCached(llmService, provider, model, !!(args && args.noCache === true));\n        const reasoning = info && info.reasoning ? {\n          efforts: info.reasoning.efforts.map((e) => ({\n            id: String(e.id),\n            name: e.name,\n            ...(e.description ? { description: e.description } : {}),\n          })),\n          ...(info.reasoning.defaultEffort ? { defaultEffort: String(info.reasoning.defaultEffort) } : {}),\n        } : undefined;\n        return {\n          ok: true,\n          provider,\n          model,\n          ...(reasoning ? { reasoning } : {}),\n          ...(info && info.context ? { context: info.context } : {}),\n          ...(info && info.defaultMaxTokens ? { defaultMaxTokens: info.defaultMaxTokens } : {}),\n        };\n      } catch (e) {\n        herr('[enhance] models/resolve failed', e);\n        return { ok: false, code: 'RESOLVE_FAILED', message: String(e && e.message ? e.message : e) };\n      }\n    });\n\n    harness.handle('models/current', async () => {\n      const adm = ctx.get('agentDefaultModel');\n      if (!adm || typeof adm.currentSelection !== 'function') {\n        return { ok: false, code: 'NO_SERVICE', message: 'agentDefaultModel unavailable' };\n      }\n      try {\n        const sel = adm.currentSelection();\n        if (!sel || typeof sel.provider !== 'string' || typeof sel.model !== 'string' || !sel.provider || !sel.model) {\n          return { ok: false, code: 'EMPTY', message: 'no current selection' };\n        }\n        return {\n          ok: true,\n          provider: sel.provider,\n          model: sel.model,\n          ...(typeof sel.reasoningEffort === 'string' && sel.reasoningEffort ? { reasoningEffort: sel.reasoningEffort } : {}),\n        };\n      } catch (e) {\n        herr('[enhance] models/current failed', e);\n        return { ok: false, code: 'CURRENT_FAILED', message: String(e && e.message ? e.message : e) };\n      }\n    });\n\n    // v19：暴露自适应解析出的默认兜底链（供 client 首装继承 / 恢复默认使用，不再硬编码 provider）\n    harness.handle('models/autochain', async (args) => {\n      const llmSvc = ctx.get('llm');\n      const adm = ctx.get('agentDefaultModel');\n      try {\n        // F8（配置卫生）：noCache 旁路 TTL——「恢复默认」始终取最新自适应链\n        const chain = await resolveAdaptiveChain(llmSvc, adm, !!(args && args.noCache === true));\n        return { ok: true, chain };\n      } catch (e) {\n        herr('[enhance] models/autochain failed', e);\n        return { ok: false, code: 'AUTOCHAIN_FAILED', message: String(e && e.message ? e.message : e) };\n      }\n    });\n\n    harness.handle('models/test', async (args) => {\n      const provider = args && typeof args.provider === 'string' ? args.provider : '';\n      const model = args && typeof args.model === 'string' ? args.model : '';\n      const reasoningEffort = args && typeof args.reasoningEffort === 'string' && args.reasoningEffort !== '' ? args.reasoningEffort : undefined;\n      const inputChars = args && typeof args.inputChars === 'number' && Number.isFinite(args.inputChars) ? args.inputChars : 0;\n      const llmService = ctx.get('llm');\n      if (!llmService || typeof llmService.stream !== 'function') {\n        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };\n      }\n      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };\n      const entry = { provider, model, ...(reasoningEffort ? { reasoningEffort } : {}) };\n      // 预校验：失败不阻断（目录 advisory，端点最终裁决；结果附 precheck 供展示）\n      let precheck = null;\n      if (llmService.resolveCallConfig) {\n        try {\n          await llmService.resolveCallConfig({ provider, model, ...(reasoningEffort ? { reasoningEffort } : {}), maxTokens: 1 });\n        } catch (e) {\n          precheck = { code: e && e.code ? String(e.code) : 'PRECHECK_FAILED', message: String(e && e.message ? e.message : e) };\n        }\n      }\n      const ref = { current: null };\n      let timedOut = false;\n      // v3.1.7（方案 2）：探测改长文（~1200 token）后，真实吞吐 75–267 tok/s 需 4–16s + TTFT；\n      // 15s 超时不够，放宽到 30s（最慢档 75 tok/s × 1200 token ≈ 16s，留足余量）。\n      const timer = ctx.timer.timeout(() => {\n        timedOut = true;\n        if (ref.current && typeof ref.current.return === 'function') {\n          try { ref.current.return(); } catch (e) { /* 忽略 */ }\n        }\n      }, 30000);\n      let r;\n      try {\n        r = await pingStream(llmService, entry, ref);\n      } finally {\n        timer();\n      }\n      if (timedOut) {\n        hlog('[enhance] test provider=' + provider + ' model=' + model + (reasoningEffort ? ' effort=' + reasoningEffort : '') + ' → timeout');\n        return { ok: false, code: 'TIMEOUT', message: friendlyMessage({ code: 'TIMEOUT' }) };\n      }\n      hlog('[enhance] test provider=' + provider + ' model=' + model + (reasoningEffort ? ' effort=' + reasoningEffort : '') + ' → ' + (r.ok ? 'ok ' + r.latencyMs + 'ms' : r.code));\n      if (r.ok && typeof r.tokensPerSecond === 'number' && Number.isFinite(r.tokensPerSecond) && typeof r.ttftMs === 'number' && Number.isFinite(r.ttftMs)) {\n        r.estimatedBaseSeconds = estimateBaseModeSeconds(r.ttftMs, r.tokensPerSecond, inputChars);\n        r.estimatedLiteSeconds = estimateLiteModeSeconds(r.ttftMs, r.tokensPerSecond, inputChars);\n      }\n      return { ...r, ...(precheck && r.ok ? { precheck } : {}) };\n    });\n\n\n    // 2026-08-17（连通性测试预计耗时）：按模型名实时聚合 DSH 会话投影统计。\n    // 性能约束：持久化会话全量日志读取很重，不能每次/每个会话都 readSession。\n    // 策略：live 会话每次走内存（快）；persisted 会话首次最多扫描 SCAN_LIMIT 个，\n    // 命中后把 model route + projection 缓存，后续调用只聚合缓存，避免卡 UI。\n    // 匹配口径：只按模型名匹配（用户要求），不区分 provider 路由。\n    const sessionModelCache = new Map();        // sid -> { route, at }\n    const sessionProjectionCache = new Map();   // sid -> { values, at }\n    const SESSION_MODEL_TTL_MS = 600000;        // persisted route 缓存 10 分钟\n    const SESSION_PROJECTION_TTL_MS = 600000;   // persisted projection 缓存 10 分钟\n    const MODEL_STATS_SCAN_LIMIT = 5;           // 单次调用最多新读多少个 persisted 会话（5 个足够命中同模型历史，避免冷启动超时）\n\n    function cachedSessionModel(sid) {\n      const hit = sessionModelCache.get(sid);\n      if (hit && Date.now() - hit.at < SESSION_MODEL_TTL_MS) return hit.route;\n      return undefined;\n    }\n\n    async function loadPersistedSession(sq, proj, sid) {\n      const snap = await sq.readSession(sid);\n      const route = extractModelRouteFromEvents(snap && snap.events);\n      sessionModelCache.set(sid, { route, at: Date.now() });\n      let projection = null;\n      try {\n        const sessionLike = { seq: (snap.events || []).length, events: snap.events || [] };\n        const pval = proj.snapshot(sessionLike);\n        projection = pval && pval.values ? pval.values : {};\n        sessionProjectionCache.set(sid, { values: projection, at: Date.now() });\n      } catch (e) {\n        projection = null;\n      }\n      return { route, projection };\n    }\n\n    async function resolveModelStats(provider, model) {\n      const sq = ctx.get('sessionQuery');\n      const proj = ctx.get('sessionProjections');\n      if (!sq || typeof sq.listSessions !== 'function' || !proj || typeof proj.snapshot !== 'function') {\n        return { ok: false, code: 'NO_STATS', message: 'session stats unavailable' };\n      }\n      const acc = { ttftMs: 0, ttftSteps: 0, decodeMs: 0, decodeTokens: 0, sessions: 0 };\n      try {\n        const records = await sq.listSessions();\n        let scanBudget = MODEL_STATS_SCAN_LIMIT;\n        for (const rec of records) {\n          const sid = rec && rec.header && rec.header.id;\n          if (!sid) continue;\n          let route;\n          let projection;\n          if (rec.live === true) {\n            // live 会话：直接走内存 Session，不落持久化缓存\n            const sessions = ctx.get('sessions');\n            const live = sessions && typeof sessions.get === 'function' ? sessions.get(sid) : undefined;\n            if (!live) continue;\n            route = extractModelRouteFromEvents(live.events);\n            try {\n              const pval = proj.snapshot(live);\n              projection = pval && pval.values ? pval.values : {};\n            } catch (e) {\n              projection = null;\n            }\n          } else {\n            const cachedRoute = cachedSessionModel(sid);\n            if (cachedRoute !== undefined) {\n              route = cachedRoute;\n              const pc = sessionProjectionCache.get(sid);\n              if (pc && Date.now() - pc.at < SESSION_PROJECTION_TTL_MS) projection = pc.values;\n            } else if (scanBudget > 0) {\n              scanBudget -= 1;\n              try {\n                const loaded = await loadPersistedSession(sq, proj, sid);\n                route = loaded.route;\n                projection = loaded.projection;\n              } catch (e) {\n                route = null;\n                projection = null;\n              }\n            }\n          }\n          if (!route || route.model !== model) continue;\n          if (projection) {\n            // 按用户要求：只按模型名匹配，不区分 provider 路由\n            accumulateProjectionStats(acc, { values: projection });\n          }\n        }\n      } catch (e) {\n        herr('[enhance] models/stats failed', e);\n        return { ok: false, code: 'STATS_FAILED', message: String(e && e.message ? e.message : e) };\n      }\n      return { ok: true, ...summarizeModelStats(acc) };\n    }\n\n    harness.handle('models/stats', async (args) => {\n      const provider = args && typeof args.provider === 'string' ? args.provider : '';\n      const model = args && typeof args.model === 'string' ? args.model : '';\n      const inputChars = args && typeof args.inputChars === 'number' && Number.isFinite(args.inputChars) ? args.inputChars : 0;\n      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };\n      const stats = await resolveModelStats(provider, model);\n      if (!stats.ok) return stats;\n      const estimatedBaseSeconds = estimateBaseModeSeconds(stats.ttftMs, stats.tokensPerSecond, inputChars);\n      const estimatedLiteSeconds = estimateLiteModeSeconds(stats.ttftMs, stats.tokensPerSecond, inputChars);\n      return { ...stats, estimatedBaseSeconds, estimatedLiteSeconds };\n    });\n\n// @dsh-plugins-inject\n\n    harness.handle('logs/last', async () => ({ ok: true, lines: LOG_RING.slice() }));\n\n    // v2.4.7（每模式独立自定义模板）：返回各模式默认提示词——client 首次切换\n    // 「自定义模板」且当前模式无内容时预填用（client 侧无内置模板文本，须 host 提供）。\n    // v2.8.0（实测修正）：补 publish 键 = SYSTEM_PUBLISH_PROMPT——此前只返回 4 模式，\n    // publish 切自定义模板预填拿到 undefined → 内容为空（用户实测反馈）。\n    // 当前 5 模式 base/lite/standard/smart 同值 = SYSTEM_PROMPT；若未来内置按模式拆分\n    // （prompts/system-<mode>.md），此 RPC 返回随生成区自动变化，client 无需改动。\n    harness.handle('template/default', async () => ({\n      ok: true,\n      // 兼容保留：defaults[mode] = T1（现有默认模板，行为不变）\n      defaults: {\n        // v3.1.8（用户指令·每模式默认模板按场景定制）：T1 默认指向模式专属模板\n        base: SYSTEM_PROMPT,\n        lite: SYSTEM_LITE_PROMPT,\n        standard: SYSTEM_STANDARD_PROMPT,\n        smart: SYSTEM_SMART_PROMPT,\n        publish: SYSTEM_PUBLISH_PROMPT,\n      },\n      // 模板体系扩展（2026-08-18 修订）：catalog[mode] = [T1, T2]——每模式 2 个内置模板，\n      // 供 client 模板选择下拉与新建自定义模板预填（T2=增量模板·保守补充未说的大逻辑/信息，每模式方向不同）\n      catalog: {\n        base: [SYSTEM_PROMPT, SYSTEM_INCREMENT_PROMPT],\n        lite: [SYSTEM_LITE_PROMPT, SYSTEM_INCREMENT_LITE_PROMPT],\n        standard: [SYSTEM_STANDARD_PROMPT, SYSTEM_INCREMENT_STANDARD_PROMPT],\n        smart: [SYSTEM_SMART_PROMPT, SYSTEM_INCREMENT_SMART_PROMPT],\n        publish: [SYSTEM_PUBLISH_PROMPT, SYSTEM_INCREMENT_PUBLISH_PROMPT],\n      },\n    }));\n\n    // ================= v2.4.0 版本检测与一键更新 RPC =================\n    // 方案「插件版本检测与一键更新方案.md」§3：检测（update/check）→ 一键拉取（update/pull）。\n    // v2.4.1（实测回填 §9-T5/T6）架构：**host 不再出网**——本部署 web.fetch 无可用 provider\n    // （实机抛 WEB_PROVIDER_UNAVAILABLE）；改由 client 浏览器直连 GitHub API（CORS 实测 200），\n    // host 只做解析/校验/比较/写入（能力均已实机验证可用）。\n    const updateCache = new Map();      // repo → { at, value }（TTL UPDATE_CACHE_TTL_MS）\n    const pullInFlight = new Set();     // repo → 拉取中（防重入 PULL_BUSY）\n\n    // v2.4.1（实测回填 §9-T5）：策略必须**带会话解析**——无会话时 workspaceRoot 回退到 DSH\n    // 安装目录且写工作区返回 FS_SANDBOX_DENIED（实机验证）；带 session 后 mode=会话预设\n    // （如 danger-full-access）、root=会话工作区（实机验证写 ok）。\n    function resolveSessionPolicy(sessionId) {\n      const sp = ctx.get('sandboxPolicy');\n      if (!sp || typeof sp.resolve !== 'function') return null;\n      let session;\n      try {\n        const ss = ctx.get('sessions');\n        if (ss && typeof ss.get === 'function' && typeof sessionId === 'string' && sessionId) {\n          session = ss.get(sessionId) || undefined;\n        }\n      } catch (e) { /* 会话解析失败 → 回退无会话策略 */ }\n      try {\n        return sp.resolve(session ? { session } : undefined);\n      } catch (e) {\n        return null;\n      }\n    }\n\n// @dsh-update-inject\n\n    // v2.6.0：update/apply 与 update/restart 已移除——更新执行迁至独立执行器\n    // （lib/updater-host.cjs，127.0.0.1:EXECUTOR_PORT；client 经 update/executorEnsure\n    // 获取执行器地址后直连）。原因：重启/重试必须脱离 dsh-web 进程（服务停 = host 死，\n    // 依赖 host 的重试必然无法送达——v2.5.5 out.log 无 update/restart 日志为证）。\n\n// @dsh-enhance-inject\n\n    ctx.effect(() => () => {\n      for (const key of [...pending.keys()]) {\n        const rec = pending.get(key);\n        if (rec && rec.iterator && typeof rec.iterator.return === 'function') {\n          try { rec.iterator.return(); } catch (e) { /* 忽略 */ }\n        }\n      }\n    });\n  },\n};";
